            var errors = sheet.querySelector('[data-errors]');
            var input = sheet.querySelector('[data-files]');
            var selected = new Set(), names = [], busy = false, ready = false, closed = false, loader = null;
            var dialog = sheet.querySelector('.tm-sheet');
