                    settings.name = fallback;
                    settings.url = fallback ? getBackgroundCssUrl(fallback) : 'none';
                    var bg = global.document.getElementById('bg1');
                    if (bg) bg.style.backgroundImage = settings.url;
                    if (mods[1].saveSettingsDebounced) mods[1].saveSettingsDebounced();
