/* Theme showcase: capture a user/character pair without changing the live chat. */
(function (global) {
    var ns = global.ThemeMgrModules = global.ThemeMgrModules || {};
    ns.createThemeShowcase = function (opts) {
        var busy = false;
        function fail(message) { throw new Error(message); }
        function findPair(chat) {
            var messages = Array.from(chat.querySelectorAll('.mes')).filter(function (message) {
                return message.getAttribute('is_system') !== 'true' && message.querySelector('.mes_text') &&
                    message.querySelector('.mes_text').textContent.trim();
            });
            for (var i = messages.length - 1; i >= 1; i--) {
                if (messages[i].getAttribute('is_user') !== 'false') continue;
                for (var j = i - 1; j >= 0; j--) {
                    if (messages[j].getAttribute('is_user') === 'true') return [messages[j], messages[i]];
                }
            }
            fail('请先打开包含一层 User 和一层角色回复的聊天');
        }
        function contextKey() {
            var context = global.SillyTavern && global.SillyTavern.getContext && global.SillyTavern.getContext();
            return context ? JSON.stringify([context.chatId, context.characterId, context.groupId]) : '';
        }
        async function captureAndSave(progress) {
            if (busy) fail('美化展示正在生成，请稍候');
            busy = true;
            var markers = [], token = 'tm-showcase-' + Date.now() + '-' + Math.random().toString(36).slice(2);
            try {
                var themeName = opts.getThemeName();
                if (!themeName) fail('请先选择并应用一个美化');
                if (opts.isThemeApplying && opts.isThemeApplying()) fail('美化仍在切换，请稍后再生成展示');
                if (global.document.querySelector('#chat .mes .mes_edit_textarea')) fail('请先完成消息编辑，再生成展示');
                var chat = global.document.getElementById('chat');
                if (!chat) fail('当前没有可截图的聊天页面');
                var pair = findPair(chat);
                var target = global.document.getElementById('sheld') || chat;
                var width = Math.round(target.getBoundingClientRect().width);
                if (!width || !target.getBoundingClientRect().height) fail('聊天页面不可见，请先打开聊天');
                var key = contextKey(), texts = pair.map(function (message) { return message.innerHTML; });
                var initialStyle = global.document.getElementById('custom-style');
                var css = initialStyle ? initialStyle.textContent : '';
                function validate() {
                    if (opts.getThemeName() !== themeName || (opts.isThemeApplying && opts.isThemeApplying()) ||
                        global.document.getElementById('chat') !== chat || contextKey() !== key ||
                        pair.some(function (message, index) { return !message.isConnected || message.innerHTML !== texts[index]; }) ||
                        (initialStyle && initialStyle.textContent !== css)) fail('截图期间美化或聊天发生变化，请重新生成');
                }
                if (typeof ns.showcaseRenderer !== 'function') fail('截图组件未加载，请刷新酒馆后重试');
                if (progress) progress('正在截取 User 和角色消息…');
                // Marker attributes only locate nodes in the renderer's cloned document.
                pair.forEach(function (message, index) {
                    markers.push({ node: message, value: message.getAttribute('data-tm-showcase') });
                    message.setAttribute('data-tm-showcase', token + '-' + index);
                });
                // Record text after markers are installed (the attribute is outside innerHTML).
                var canvas = await ns.showcaseRenderer(target, {
                    logging: false, useCORS: true, allowTaint: false, backgroundColor: null,
                    scale: Math.min(2, 1200 / width), imageTimeout: 10000,
                    ignoreElements: function (element) {
                        return element.matches && element.matches('.tm-overlay,.tm-sheet-overlay,.tm-showcase-busy,#tm-fab-main,#theme-mgr-ext-btn');
                    },
                    onclone: async function (doc) {
                        var cloneChat = doc.getElementById('chat');
                        var cloneTarget = doc.getElementById('sheld') || cloneChat;
                        var chosen = [0, 1].map(function (index) { return doc.querySelector('[data-tm-showcase="' + token + '-' + index + '"]'); });
                        if (!cloneChat || chosen.some(function (message) { return !message; })) fail('聊天消息已变化，请重试');
                        Array.from(cloneChat.children).forEach(function (element) {
                            if (!chosen.some(function (message) { return element === message || element.contains(message); })) element.remove();
                        });
                        // Keep native #sheld/#chat ancestors so existing theme selectors still match.
                        chosen.forEach(function (message) { if (message.parentNode !== cloneChat) cloneChat.appendChild(message); });
                        cloneChat.querySelectorAll('.mes').forEach(function (message) { if (chosen.indexOf(message) === -1) message.remove(); });
                        if (cloneTarget !== cloneChat) Array.from(cloneTarget.children).forEach(function (element) {
                            if (element !== cloneChat && !element.contains(cloneChat)) element.remove();
                        });
                        var styles = doc.createElement('style');
                        styles.textContent = '*{animation:none!important;transition:none!important;caret-color:transparent!important;}' +
                            '#sheld{position:absolute!important;top:0!important;left:0!important;transform:none!important;margin:0!important;min-height:0!important;max-height:none!important;height:auto!important;width:' + width + 'px!important;overflow:hidden!important;}' +
                            '#chat{position:relative!important;top:auto!important;left:auto!important;transform:none!important;flex:none!important;min-height:0!important;max-height:none!important;height:auto!important;width:100%!important;overflow:visible!important;scroll-behavior:auto!important;}' +
                            '#chat .mes{content-visibility:visible!important;}' +
                            '#chat .mes_text{max-height:900px!important;overflow:hidden!important;}' +
                            '#chat .mes_buttons,#chat .swipe_left,#chat .swipe_right,#chat .swipes-counter,#chat .mes_edit_buttons{visibility:hidden!important;}' +
                            '.tm-showcase-background{position:absolute!important;inset:0!important;pointer-events:none!important;z-index:0!important;}';
                        doc.head.appendChild(styles);
                        cloneChat.scrollTop = 0;
                        var backdrop = doc.getElementById('bg1');
                        var backdrop2 = doc.getElementById('bg2');
                        // Canvas captures descendants only; bring the native background into the target clone.
                        var bgHolder = doc.createElement('div');
                        bgHolder.className = 'tm-showcase-background';
                        [backdrop, backdrop2].forEach(function (source) {
                            if (!source) return;
                            var background = source.cloneNode(true);
                            var computed = doc.defaultView.getComputedStyle(source);
                            background.removeAttribute('id');
                            background.style.cssText = 'position:absolute!important;inset:0!important;width:100%!important;height:100%!important;z-index:auto!important;';
                            ['background-image','background-size','background-position','background-repeat','background-color','opacity','filter'].forEach(function (property) {
                                background.style.setProperty(property, computed.getPropertyValue(property), 'important');
                            });
                            bgHolder.appendChild(background);
                        });
                        if (cloneTarget === cloneChat) {
                            chosen.forEach(function (message) { message.style.setProperty('position', 'relative'); message.style.setProperty('z-index', '1'); });
                        } else cloneChat.style.setProperty('z-index', '1');
                        cloneTarget.insertBefore(bgHolder, cloneTarget.firstChild);
                        if (doc.fonts && doc.fonts.ready) await doc.fonts.ready;
                    },
                });
                validate();
                if (!canvas.width || !canvas.height) fail('截图为空，请重试');
                var image = canvas.toDataURL('image/jpeg', 0.9);
                if (progress) progress('正在保存展示封面…');
                var thumb = await opts.makeThumbnail(image);
                validate();
                var urls = await Promise.all([opts.uploadImage(image), opts.uploadImage(thumb)]);
                validate();
                // Read fresh metadata after rendering/upload; preserve concurrent unrelated changes.
                var data = opts.load();
                if (opts.hasTheme && !opts.hasTheme(themeName)) fail('该美化已删除或改名，未保存展示封面');
                var meta = opts.ensureMeta(data, themeName);
                var previous = { imageData: meta.imageData, thumbData: meta.thumbData, crop: meta.crop };
                meta.imageData = urls[0] || image;
                meta.thumbData = urls[1] || thumb;
                meta.crop = { zoom: 1, posX: 50, posY: 50 };
                try { await opts.save(data); }
                catch (error) {
                    // Some legacy stores expose a shared in-memory metadata object.
                    if (meta.imageData === (urls[0] || image)) Object.assign(meta, previous);
                    throw error;
                }
                if (opts.onSaved) opts.onSaved(themeName);
                return { themeName: themeName, imageData: image };
            } finally {
                markers.forEach(function (marker) {
                    if (marker.value === null) marker.node.removeAttribute('data-tm-showcase');
                    else marker.node.setAttribute('data-tm-showcase', marker.value);
                });
                busy = false;
            }
        }
        return { captureAndSave: captureAndSave, isBusy: function () { return busy; }, findPair: findPair };
    };
})(window);


