    // ── 分类栏 ───────────────────────────────────────────────
    function bindCatbarMouseScroll(catbar) {
        if (!catbar || catbar._tmMouseScrollBound) return;
        var drag = { down: false, moved: false, startX: 0, scrollLeft: 0 };

        function stopDrag() {
            if (!drag.down) return;
            drag.down = false;
            catbar.classList.remove('dragging');
            catbar.style.userSelect = '';
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);
            setTimeout(function () { drag.moved = false; }, 0);
        }
        function onMouseMove(e) {
            if (!drag.down) return;
            var dx = e.pageX - drag.startX;
            if (Math.abs(dx) > 3) drag.moved = true;
            if (drag.moved) e.preventDefault();
            catbar.scrollLeft = drag.scrollLeft - dx;
        }
        function onMouseUp() {
            stopDrag();
        }

        catbar.addEventListener('wheel', function (e) {
            var delta = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
            if (Math.abs(delta) <= 0) return;
            e.preventDefault();
            catbar.scrollLeft += delta;
        }, { passive: false });

        catbar.addEventListener('mousedown', function (e) {
            if (e.button !== 0) return;
            drag.down = true;
            drag.moved = false;
            drag.startX = e.pageX;
            drag.scrollLeft = catbar.scrollLeft;
            catbar.classList.add('dragging');
            catbar.style.userSelect = 'none';
            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        });

        catbar.addEventListener('click', function (e) {
            if (!drag.moved) return;
            e.preventDefault();
            e.stopPropagation();
        }, true);

        catbar._tmMouseScrollBound = true;
    }

    function renderCatbar() {
        var nav = document.getElementById('tm-category-nav');
        var catbar = document.getElementById('tm-catbar');
        var panel = document.getElementById('tm-category-panel');
        var expand = document.getElementById('tm-category-expand');
        if (!nav || !catbar || !panel || !expand) return;
        var d = load();
        if (curCat === '__day-night__' || (curCat !== '__all__' && curCat !== '__uncategorized__' && d.categories.indexOf(curCat) === -1)) curCat = '__all__';
        nav.style.display = '';
        var html = '<button class="tm-catbtn' + (curCat === '__all__' ? ' on' : '') + '" data-c="__all__">全部</button>';
        html += '<button class="tm-catbtn' + (curCat === '__uncategorized__' ? ' on' : '') + '" data-c="__uncategorized__">未分类</button>';
        d.categories.forEach(function (c) {
            html += '<button class="tm-catbtn' + (curCat === c ? ' on' : '') + '" data-c="' + esc(c) + '">' + esc(c) + '</button>';
        });
        catbar.innerHTML = html;
        function selectCategory(category) {
            curCat = category;
            categoryPanelOpen = false;
            categoryCreateOpen = false;
            renderCatbar();
            renderGrid();
        }
        catbar.querySelectorAll('.tm-catbtn').forEach(function (btn) {
            btn.addEventListener('click', function () { selectCategory(btn.dataset.c); });
        });
        expand.setAttribute('aria-expanded', categoryPanelOpen ? 'true' : 'false');
        expand.title = categoryPanelOpen ? '收起全部分类' : '展开全部分类';
        expand.setAttribute('aria-label', expand.title);
        expand.innerHTML = '<i class="fa-solid fa-chevron-' + (categoryPanelOpen ? 'up' : 'down') + '"></i>';
        expand.onclick = function () {
            categoryPanelOpen = !categoryPanelOpen;
            if (!categoryPanelOpen) categoryCreateOpen = false;
            renderCatbar();
        };

        panel.hidden = !categoryPanelOpen;
        if (!categoryPanelOpen) {
            panel.innerHTML = '';
        } else {
            var panelButtons = '<button class="tm-category-panel-item' + (curCat === '__all__' ? ' on' : '') + '" data-panel-category="__all__">全部</button>' +
                '<button class="tm-category-panel-item' + (curCat === '__uncategorized__' ? ' on' : '') + '" data-panel-category="__uncategorized__">未分类</button>';
            d.categories.forEach(function (category) {
                panelButtons += '<button class="tm-category-panel-item' + (curCat === category ? ' on' : '') + '" data-panel-category="' + esc(category) + '">' + esc(category) + '</button>';
            });
            panel.innerHTML = '<div class="tm-category-panel-head"><strong>全部分类</strong><small>选择后自动收起</small></div>' +
                '<div class="tm-category-panel-grid">' + panelButtons + '</div>' +
                '<div class="tm-category-panel-actions">' +
                '<button type="button" class="tm-btn tm-btn-outline" id="tm-category-panel-new"><i class="fa-solid fa-plus"></i> 新建分类</button>' +
                '<button type="button" class="tm-btn tm-btn-outline" id="tm-category-panel-sort"><i class="fa-solid fa-arrow-down-wide-short"></i> 拖拽排序</button>' +
                '<button type="button" class="tm-btn tm-btn-outline" id="tm-category-panel-auto"><i class="fa-solid fa-folder-tree"></i> 自动分类</button>' +
                '</div>' +
                (categoryCreateOpen ? '<div class="tm-category-panel-create"><input type="text" id="tm-category-panel-input" maxlength="40" placeholder="新分类名称…"><button type="button" class="tm-btn tm-btn-safe" id="tm-category-panel-add">添加</button></div>' : '');
            panel.querySelectorAll('[data-panel-category]').forEach(function (button) {
                button.addEventListener('click', function () { selectCategory(button.dataset.panelCategory); });
            });
            panel.querySelector('#tm-category-panel-new').addEventListener('click', function () {
                categoryCreateOpen = !categoryCreateOpen;
                renderCatbar();
                var input = document.getElementById('tm-category-panel-input');
                if (input) input.focus();
            });
            panel.querySelector('#tm-category-panel-sort').addEventListener('click', function () { openCatsSheet(); });
            panel.querySelector('#tm-category-panel-auto').addEventListener('click', openAutoCategorySheet);
            var input = panel.querySelector('#tm-category-panel-input');
            var add = panel.querySelector('#tm-category-panel-add');
            if (input && add) {
                function addCategory() {
                    var name = input.value.trim();
                    if (!name) return;
                    var dd = load();
                    if (metadataApi.isReservedCategoryName(name)) { toast('该名称为内部保留名称，请使用其他分类名', true); return; }
                    if (dd.categories.indexOf(name) !== -1) { toast('分类已存在', true); return; }
                    dd.categories.push(name);
                    save(dd);
                    curCat = name;
                    categoryPanelOpen = false;
                    categoryCreateOpen = false;
                    renderCatbar();
                    renderGrid();
                    toast('分类「' + name + '」已添加');
                }
                add.addEventListener('click', addCategory);
                input.addEventListener('keydown', function (event) {
                    if (event.key === 'Enter') { event.preventDefault(); addCategory(); }
                });
            }
        }
        bindCatbarMouseScroll(catbar);
    }

    function collectThemeTags(data) {
        var tags = [];
        var seen = new Set();
        getLogicalItems(data || load()).forEach(function (item) {
            var meta = getItemMeta(data || load(), item);
            (Array.isArray(meta.tags) ? meta.tags : []).forEach(function (tag) {
                tag = String(tag || '').trim();
                if (!tag || seen.has(tag)) return;
                seen.add(tag);
                tags.push(tag);
            });
        });
        return tags.sort(function (a, b) { return a.localeCompare(b, 'zh-CN'); });
    }

    function buildDisclosureHtml(id, title, icon, content) {
        return '<details class="tm-disclosure" id="' + id + '"><summary><span><i class="fa-solid ' + icon + '"></i>' + title + '</span><i class="fa-solid fa-chevron-right tm-disclosure-chevron"></i></summary><div class="tm-disclosure-body">' + content + '</div></details>';
    }

    function openChoicePicker(options) {
        options = options || {};
        var items = (Array.isArray(options.items) ? options.items : []).map(function (item) {
            return {
                value: String(item && item.value || ''),
                label: String(item && item.label || ''),
                hint: String(item && item.hint || ''),
                icon: String(item && item.icon || options.icon || 'fa-circle-dot'),
            };
        }).filter(function (item) { return item.value && item.label; });
        var selected = String(options.selected || '');
        var sheet = createSheet([
            '<div class="tm-sheet-title"><i class="fa-solid ' + esc(options.icon || 'fa-list') + '"></i>' + esc(options.title || '请选择') + '</div>',
            options.hint ? '<div class="tm-hint tm-picker-hint">' + esc(options.hint) + '</div>' : '',
            '<input type="text" class="tm-picker-search" data-choice-picker-search placeholder="' + esc(options.searchPlaceholder || '搜索…') + '" autocomplete="off" />',
            '<div class="tm-picker-list" data-choice-picker-list></div>',
            '<div class="tm-edit-foot"><button type="button" class="tm-btn tm-btn-outline" data-choice-picker-cancel>取消</button></div>',
        ].join(''));
        var search = sheet.querySelector('[data-choice-picker-search]');
        var list = sheet.querySelector('[data-choice-picker-list]');
        function renderChoices() {
            var query = search.value.trim().toLocaleLowerCase();
            var filtered = items.filter(function (item) {
                return !query || (item.label + '\n' + item.hint).toLocaleLowerCase().indexOf(query) !== -1;
            });
            list.innerHTML = filtered.length ? filtered.map(function (item) {
                var active = item.value === selected;
                return '<button type="button" class="tm-picker-row' + (active ? ' is-selected' : '') + '" data-choice-picker-value="' + esc(item.value) + '">' +
                    '<span><i class="fa-solid ' + esc(item.icon) + '"></i><span class="tm-picker-row-copy"><strong>' + esc(item.label) + '</strong>' +
                    (item.hint ? '<small>' + esc(item.hint) + '</small>' : '') + '</span></span>' +
                    '<i class="fa-solid ' + (active ? 'fa-check' : 'fa-chevron-right') + '"></i></button>';
            }).join('') : '<div class="tm-picker-empty">' + esc(query ? (options.emptySearchText || '没有匹配项') : (options.emptyText || '暂无可选项')) + '</div>';
        }
        list.addEventListener('click', function (event) {
            var button = event.target && event.target.closest ? event.target.closest('[data-choice-picker-value]') : null;
            if (!button || !list.contains(button)) return;
            var value = button.dataset.choicePickerValue || '';
            var item = items.find(function (candidate) { return candidate.value === value; });
            closeSheet(sheet);
            if (item && typeof options.onSelect === 'function') options.onSelect(value, item);
        });
        search.addEventListener('input', renderChoices);
        sheet.querySelector('[data-choice-picker-cancel]').addEventListener('click', function () { closeSheet(sheet); });
        renderChoices();
        return sheet;
    }

    function openCategoryPicker(options) {
        options = options || {};
        var data = load();
        var categories = (Array.isArray(options.categories) ? options.categories : (data.categories || [])).slice();
        var selected = String(options.selected || '');
        var rows = categories.map(function (category) {
            var active = category === selected;
            return '<button type="button" class="tm-picker-row' + (active ? ' is-selected' : '') + '" data-picker-category="' + esc(category) + '">' +
                '<span><i class="fa-solid fa-folder"></i><strong>' + esc(category) + '</strong></span>' +
                (active ? '<i class="fa-solid fa-check"></i>' : '<i class="fa-solid fa-chevron-right"></i>') + '</button>';
        }).join('');
        if (!rows) rows = '<div class="tm-picker-empty">还没有分类，请先到设置中的分类管理添加</div>';
        var sheet = createSheet([
            '<div class="tm-sheet-title"><i class="fa-solid fa-folder"></i>' + esc(options.title || '选择分类') + '</div>',
            options.hint ? '<div class="tm-hint tm-picker-hint">' + esc(options.hint) + '</div>' : '',
            '<div class="tm-picker-list">' + rows + '</div>',
            options.allowClear ? '<div class="tm-picker-danger-zone"><button type="button" class="tm-btn tm-btn-outline tm-picker-clear" id="tm-category-picker-clear"><i class="fa-solid fa-eraser"></i> 设为无分类</button></div>' : '',
            '<div class="tm-edit-foot"><button type="button" class="tm-btn tm-btn-outline" id="tm-category-picker-cancel">取消</button></div>',
        ].join(''));
        sheet.querySelectorAll('[data-picker-category]').forEach(function (button) {
            button.addEventListener('click', function () {
                closeSheet(sheet);
                if (typeof options.onSelect === 'function') options.onSelect(button.dataset.pickerCategory || '');
            });
        });
        var clearButton = sheet.querySelector('#tm-category-picker-clear');
        if (clearButton) clearButton.addEventListener('click', function () {
            closeSheet(sheet);
            if (typeof options.onSelect === 'function') options.onSelect('');
        });
        sheet.querySelector('#tm-category-picker-cancel').addEventListener('click', function () { closeSheet(sheet); });
        return sheet;
    }

    function openCategoryRenameSheet(category, onRenamed) {
        var sheet = createSheet([
            '<div class="tm-sheet-title"><i class="fa-solid fa-i-cursor"></i>重命名分类</div>',
            '<div class="tm-field"><label>分类名称</label><input type="text" id="tm-category-rename-input" maxlength="40" value="' + esc(category) + '" /></div>',
            '<div class="tm-edit-foot"><button type="button" class="tm-btn tm-btn-outline" id="tm-category-rename-cancel">取消</button><button type="button" class="tm-btn tm-btn-safe" id="tm-category-rename-save">保存</button></div>',
        ].join(''));
        var input = sheet.querySelector('#tm-category-rename-input');
        function submit() {
            var name = input.value.trim();
            if (!name || name === category) { closeSheet(sheet); return; }
            var data = load();
            var result = metadataApi.renameCategory(data, category, name);
            if (!result.ok) {
                var message = result.reason === 'collision'
                    ? '目标分类已存在，重命名已取消'
                    : (result.reason === 'reserved' ? '该名称为内部保留名称，请使用其他分类名' : '分类状态无法安全确认，重命名已取消');
                toast(message, true);
                return;
            }
            save(data);
            closeSheet(sheet);
            if (typeof onRenamed === 'function') onRenamed(name);
        }
        sheet.querySelector('#tm-category-rename-save').addEventListener('click', submit);
        sheet.querySelector('#tm-category-rename-cancel').addEventListener('click', function () { closeSheet(sheet); });
        input.addEventListener('keydown', function (event) {
            if (event.key === 'Enter') { event.preventDefault(); submit(); }
        });
        return sheet;
    }

    function openTagPicker(options) {
        options = options || {};
        var knownTags = (Array.isArray(options.knownTags) ? options.knownTags : collectThemeTags(load())).slice();
        var selectedTags = Array.isArray(options.selectedTags) ? options.selectedTags.slice() : [];
        var selected = new Set(selectedTags.map(function (tag) { return String(tag || '').trim(); }).filter(Boolean));
        selected.forEach(function (tag) { if (knownTags.indexOf(tag) === -1) knownTags.push(tag); });
        knownTags.sort(function (a, b) { return a.localeCompare(b, 'zh-CN'); });
        var sheet = createSheet([
            '<div class="tm-sheet-title"><i class="fa-solid fa-tags"></i>' + esc(options.title || '管理标签') + '</div>',
            options.hint ? '<div class="tm-hint tm-picker-hint">' + esc(options.hint) + '</div>' : '',
            '<div class="tm-tag-picker">',
            '<input type="text" class="tm-picker-search" id="tm-tag-picker-search" placeholder="搜索已有标签…" autocomplete="off" />',
            '<div class="tm-picker-list tm-tag-picker-list" id="tm-tag-picker-list"></div>',
            '<div class="tm-picker-add"><input type="text" id="tm-tag-picker-new" placeholder="输入新标签…" autocomplete="off" /><button type="button" class="tm-btn tm-btn-safe" id="tm-tag-picker-add">添加</button></div>',
            options.allowClear ? '<div class="tm-picker-danger-zone"><button type="button" class="tm-btn tm-btn-outline tm-picker-clear" id="tm-tag-picker-clear"><i class="fa-solid fa-eraser"></i> 清除全部标签</button></div>' : '',
            '</div>',
            '<div class="tm-edit-foot"><button type="button" class="tm-btn tm-btn-outline" id="tm-tag-picker-cancel">取消</button><button type="button" class="tm-btn tm-btn-safe" id="tm-tag-picker-apply">应用</button></div>',
        ].join(''));
        var list = sheet.querySelector('#tm-tag-picker-list');
        var search = sheet.querySelector('#tm-tag-picker-search');
        var input = sheet.querySelector('#tm-tag-picker-new');

        function renderTags() {
            var query = search.value.trim().toLocaleLowerCase();
            var filtered = knownTags.filter(function (tag) { return !query || tag.toLocaleLowerCase().indexOf(query) !== -1; });
            list.innerHTML = filtered.length ? filtered.map(function (tag) {
                var active = selected.has(tag);
                return '<button type="button" class="tm-picker-row tm-tag-picker-row' + (active ? ' is-selected' : '') + '" data-picker-tag="' + esc(tag) + '">' +
                    '<span><i class="fa-solid fa-tag"></i><strong>' + esc(tag) + '</strong></span>' +
                    '<i class="fa-solid ' + (active ? 'fa-check' : 'fa-plus') + '"></i></button>';
            }).join('') : '<div class="tm-picker-empty">' + (query ? '没有匹配的标签' : '还没有标签，可以在下方添加') + '</div>';
        }
        function addTag() {
            var tag = input.value.trim();
            if (!tag) { toast('请输入标签', true); return; }
            selected.add(tag);
            if (knownTags.indexOf(tag) === -1) {
                knownTags.push(tag);
                knownTags.sort(function (a, b) { return a.localeCompare(b, 'zh-CN'); });
            }
            input.value = '';
            search.value = '';
            renderTags();
        }
        list.addEventListener('click', function (event) {
            var button = event.target && event.target.closest ? event.target.closest('[data-picker-tag]') : null;
            if (!button || !list.contains(button)) return;
            var tag = button.dataset.pickerTag;
            if (selected.has(tag)) selected.delete(tag); else selected.add(tag);
            renderTags();
        });
        search.addEventListener('input', renderTags);
        sheet.querySelector('#tm-tag-picker-add').addEventListener('click', addTag);
        input.addEventListener('keydown', function (event) {
            if (event.key === 'Enter') { event.preventDefault(); addTag(); }
        });
        sheet.querySelector('#tm-tag-picker-apply').addEventListener('click', function () {
            var values = Array.from(selected);
            if (options.requireSelection && values.length === 0) { toast('请先选择或添加标签', true); return; }
            closeSheet(sheet);
            if (typeof options.onApply === 'function') options.onApply(values);
        });
        var clearButton = sheet.querySelector('#tm-tag-picker-clear');
        if (clearButton) clearButton.addEventListener('click', function () {
            closeSheet(sheet);
            if (typeof options.onClear === 'function') options.onClear();
            else if (typeof options.onApply === 'function') options.onApply([]);
        });
        sheet.querySelector('#tm-tag-picker-cancel').addEventListener('click', function () { closeSheet(sheet); });
        renderTags();
        return sheet;
    }

    // ── 网格 ─────────────────────────────────────────────────
    function buildGridCardHtml(item, d, curTheme, view) {
        view = view || buildLibraryView(d);
        var meta = view.metaByKey[item.key] || getItemMeta(d, item);
        var isActive = isItemActive(item, curTheme);
        var selected = batchSelected.has(item.key);
        var checkBox = batchMode
            ? '<div class="tm-card-check' + (selected ? ' checked' : '') + '" data-key="' + esc(item.key) + '"><i class="fa-solid fa-check"></i></div>'
            : '';
        var badge = (isActive && !batchMode) ? '<div class="tm-badge-on"><i class="fa-solid fa-check"></i></div>' : '';
        var starBadge = (meta.starred && !batchMode) ? '<div class="tm-badge-star"><i class="fa-solid fa-star"></i></div>' : '';
        var freqBadge = (d.showFreq !== false && (meta.useCount || 0) > 5 && !batchMode)
            ? '<div class="tm-badge-freq">' + meta.useCount + '次</div>'
            : '';
        var menuBtn = batchMode ? '' : '<button class="tm-card-menu" data-key="' + esc(item.key) + '" title="编辑美化" aria-label="编辑「' + esc(item.name) + '」"><i class="fa-solid fa-ellipsis"></i></button>';
        var conflictNames = getAmbiguousThemeNames(item);
        var inventoryConflict = conflictNames.length > 0;
        var tagText = inventoryConflict
            ? '酒馆库存重复 ' + (themeNameConflictCounts[conflictNames[0]] || 2) + ' 份 · 禁止编辑删除'
            : ((meta.tags && meta.tags.length > 0) ? meta.tags.join(' · ') : (meta.author || ''));
        var cardStateClasses = (isActive ? ' on' : '') + (selected ? ' batch-sel' : '') + (inventoryConflict ? ' inventory-conflict' : '');
        var conflictTitle = inventoryConflict ? ' title="酒馆主题库存中这个名称出现多份；可切换，但无法安全编辑或删除"' : '';

        if (d.noImageMode === true) {
            return '<div class="tm-card tm-card-text' + cardStateClasses + '" data-key="' + esc(item.key) + '"' + conflictTitle + '>' +
                checkBox +
                '<div class="tm-card-text-icon" aria-hidden="true"><i class="fa-solid fa-palette"></i></div>' +
                '<div class="tm-card-info"><div class="tm-card-name">' + esc(item.name) + '</div>' +
                (tagText ? '<div class="tm-card-tag">' + esc(tagText) + '</div>' : '') +
                '</div><div class="tm-card-text-actions">' + badge + starBadge + freqBadge + menuBtn + '</div></div>';
        }

        var displayTheme = getItemDisplayTheme(d, item);
        var variantMeta = d.themeMeta[displayTheme] || {};
        var previewPresentation = imageToolsApi.resolvePreviewPresentation(variantMeta);
        var previewImage = previewPresentation.hasImage;
        var previewView = previewPresentation.view;
        var previewStyle = '--tm-image-focus-x:' + esc(previewView.posX) + '%;' +
            '--tm-image-focus-y:' + esc(previewView.posY) + '%;' +
            '--tm-image-zoom:' + esc(previewView.zoom) + ';';
        var imgContent = previewImage
            ? '<div class="tm-card-preview-slot" style="' + previewStyle + '">' +
                '<img src="' + esc(imageLoaderApi.PLACEHOLDER_SRC) + '" data-theme-key="' + esc(item.key) + '" data-image-state="idle" alt="' + esc(item.name) + '" decoding="async" />' +
                '</div>'
            : '<div class="tm-card-noimg"><i class="fa-solid fa-palette"></i><span>' + esc(item.name.slice(0, 6)) + '</span></div>';

        return '<div class="tm-card' + cardStateClasses + (previewImage ? '' : ' no-img') + '" data-key="' + esc(item.key) + '"' + conflictTitle + '>' +
            '<div class="tm-card-img">' + checkBox + imgContent + badge + starBadge + freqBadge + menuBtn + '</div>' +
            '<div class="tm-card-info"><div class="tm-card-name">' + esc(item.name) + '</div>' +
            (tagText ? '<div class="tm-card-tag">' + esc(tagText) + '</div>' : '') +
            '</div></div>';
    }

    function buildSeriesLayoutUnits(d, sortedItems, cat, query, view) {
        view = view || buildLibraryView(d);
        var groups = view.seriesGroups;
        var membership = view.seriesMembership;
        var unitBySeries = Object.create(null);
        var rawUnits = [];

        sortedItems.forEach(function (item) {
            var targetKey = item.kind === 'pair' ? 'pair:' + item.pairId : 'theme:' + item.themeName;
            var seriesId = targetKey ? membership[targetKey] : '';
            var group = seriesId ? groups[seriesId] : null;
            if (!group) {
                rawUnits.push({ type: 'item', item: item });
                return;
            }
            var unit = unitBySeries[group.id];
            if (!unit) {
                unit = { type: 'series', group: group, items: [] };
                unitBySeries[group.id] = unit;
                rawUnits.push(unit);
            }
            unit.items.push(item);
        });

        var filtered = rawUnits.filter(function (unit) {
            if (unit.type === 'item') {
                if (!displayCategoryMatches((view.metaByKey[unit.item.key] || {}).category, cat)) return false;
                return itemMatchesSearch(d, unit.item, query);
            }
            if (!displayCategoryMatches(unit.group.category, cat)) return false;
            if (!query) return true;
            var q = String(query).toLocaleLowerCase();
            return unit.group.name.toLowerCase().indexOf(q) !== -1 || unit.items.some(function (item) {
                return itemMatchesSearch(d, item, query);
            });
        });
        var displayedItems = [];
        filtered.forEach(function (unit) {
            if (unit.type === 'item') displayedItems.push(unit.item);
            else unit.items.forEach(function (item) { displayedItems.push(item); });
        });
        return { units: filtered, displayedItems: displayedItems };
    }

    function alignSeriesUnitsForGrid(units, columns) {
        var output = [];
        var rowCards = [];
        var deferredSeries = [];
        function flushRow() {
            rowCards.splice(0).forEach(function (unit) { output.push(unit); });
            deferredSeries.splice(0).forEach(function (unit) { output.push(unit); });
        }
        (units || []).forEach(function (unit) {
            if (unit.type === 'item') {
                rowCards.push(unit);
                if (rowCards.length >= columns) flushRow();
                return;
            }
            if (rowCards.length === 0) output.push(unit);
            else deferredSeries.push(unit);
        });
        if (rowCards.length > 0 || deferredSeries.length > 0) flushRow();
        return output;
    }

    function buildSeriesBlockHtml(unit, d, curTheme, view) {
        var group = unit.group;
        var expanded = expandedSeriesId === group.id;
        var previewsHidden = d.noImageMode === true || (d.hideSeriesPreviews === true && !batchMode);
        var controlId = 'tm-series-members-' + group.id;
        return '<section class="tm-series-block' + (expanded ? ' is-expanded' : '') + (previewsHidden ? ' tm-series-preview-hidden' : '') + '" data-series-id="' + esc(group.id) + '">' +
            '<div class="tm-series-head">' +
            '<button type="button" class="tm-series-manage" data-series-id="' + esc(group.id) + '" title="管理系列">' +
            '<i class="fa-solid fa-layer-group"></i><span>' + esc(group.name) + '</span><small>' + group.members.length + ' 款</small></button>' +
            '<button type="button" class="tm-series-toggle" data-series-id="' + esc(group.id) + '" aria-expanded="' + (expanded ? 'true' : 'false') + '" aria-controls="' + esc(controlId) + '" title="' + (expanded ? '收起系列' : '展开全系列') + '">' +
            '<i class="fa-solid fa-chevron-down"></i></button></div>' +
            '<div class="tm-series-track" id="' + esc(controlId) + '">' +
            unit.items.map(function (item) { return buildGridCardHtml(item, d, curTheme, view); }).join('') +
            '</div></section>';
    }

    function captureSeriesScrollPositions(area) {
        if (!area) return;
        area.querySelectorAll('.tm-series-block').forEach(function (block) {
            var track = block.querySelector('.tm-series-track');
            if (track && !block.classList.contains('is-expanded')) {
                seriesScrollPositions[block.dataset.seriesId] = track.scrollLeft;
            }
        });
    }

    function bindSeriesRailEvents(area) {
        if (!area) return;
        area.querySelectorAll('.tm-series-block').forEach(function (block) {
            if (block._tmSeriesRailEventsBound) return;
            block._tmSeriesRailEventsBound = true;
            var seriesId = block.dataset.seriesId;
            var track = block.querySelector('.tm-series-track');
            var savedLeft = Number(seriesScrollPositions[seriesId]) || 0;
            if (track && !block.classList.contains('is-expanded')) track.scrollLeft = savedLeft;

            var manage = block.querySelector('.tm-series-manage');
            if (manage) manage.addEventListener('click', function () { openSeriesManageSheet(seriesId); });
            var toggle = block.querySelector('.tm-series-toggle');
            if (toggle) toggle.addEventListener('click', function () {
                var opening = !block.classList.contains('is-expanded');
                var previous = area.querySelector('.tm-series-block.is-expanded');
                if (opening && previous && previous !== block) {
                    previous.classList.remove('is-expanded');
                    var previousToggle = previous.querySelector('.tm-series-toggle');
                    if (previousToggle) {
                        previousToggle.setAttribute('aria-expanded', 'false');
                        previousToggle.title = '展开全系列';
                    }
                    var previousTrack = previous.querySelector('.tm-series-track');
                    if (previousTrack) previousTrack.scrollLeft = Number(seriesScrollPositions[previous.dataset.seriesId]) || 0;
                }
                if (opening) {
                    if (track) seriesScrollPositions[seriesId] = track.scrollLeft;
                    block.classList.add('is-expanded');
                    expandedSeriesId = seriesId;
                } else {
                    block.classList.remove('is-expanded');
                    expandedSeriesId = '';
                    if (track) track.scrollLeft = Number(seriesScrollPositions[seriesId]) || 0;
                }
                toggle.setAttribute('aria-expanded', opening ? 'true' : 'false');
                toggle.title = opening ? '收起系列' : '展开全系列';
            });

            if (!track) return;
            track.addEventListener('scroll', function () {
                if (!block.classList.contains('is-expanded')) seriesScrollPositions[seriesId] = track.scrollLeft;
            }, { passive: true });
            var pointerStartX = 0;
            var pointerStartY = 0;
            var pointerStartScroll = 0;
            var pointerType = '';
            var moved = false;
            var guardUntil = 0;
            track.addEventListener('pointerdown', function (event) {
                if (block.classList.contains('is-expanded') || (event.pointerType === 'mouse' && event.button !== 0)) return;
                pointerStartX = event.clientX;
                pointerStartY = event.clientY;
                pointerStartScroll = track.scrollLeft;
                pointerType = event.pointerType;
                moved = false;
                if (pointerType === 'mouse') {
                    track.classList.add('is-dragging');
                    try { track.setPointerCapture(event.pointerId); } catch (e) {}
                }
            });
            track.addEventListener('pointermove', function (event) {
                if (!pointerType || block.classList.contains('is-expanded')) return;
                var dx = event.clientX - pointerStartX;
                var dy = event.clientY - pointerStartY;
                if (Math.abs(dx) > 8 && Math.abs(dx) > Math.abs(dy)) moved = true;
                if (pointerType === 'mouse' && moved) {
                    event.preventDefault();
                    track.scrollLeft = pointerStartScroll - dx;
                }
            });
            function finishPointer(event) {
                if (moved || Math.abs(track.scrollLeft - pointerStartScroll) > 5) guardUntil = Date.now() + 260;
                if (event && pointerType === 'mouse') {
                    try { track.releasePointerCapture(event.pointerId); } catch (e) {}
                }
                pointerType = '';
                track.classList.remove('is-dragging');
            }
            track.addEventListener('pointerup', finishPointer);
            track.addEventListener('pointercancel', finishPointer);
            track.addEventListener('click', function (event) {
                if (Date.now() > guardUntil) return;
                event.preventDefault();
                event.stopPropagation();
            }, true);
            track.addEventListener('wheel', function (event) {
                if (block.classList.contains('is-expanded') || track.scrollWidth <= track.clientWidth) return;
                var delta = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
                if (!delta) return;
                var before = track.scrollLeft;
                track.scrollLeft += delta;
                if (track.scrollLeft !== before) event.preventDefault();
            }, { passive: false });
        });
    }

    function syncBatchActionState(d) {
        var count = document.getElementById('tm-batch-count');
        if (count) count.textContent = batchSelected.size;
        var pairButton = document.getElementById('tm-batch-day-night');
        if (pairButton) {
            pairButton.disabled = batchDeleting || batchSelected.size !== 2 || !getBatchSelectedKeys().every(function (key) {
                var item = getLogicalItem(key, d || load());
                return item && item.kind === 'theme';
            });
        }
        var seriesButton = document.getElementById('tm-batch-series');
        if (seriesButton) seriesButton.disabled = batchDeleting || batchSelected.size === 0;
    }

    function cancelSearchDebounce() {
        if (searchDebounceTimer !== null) clearTimeout(searchDebounceTimer);
        searchDebounceTimer = null;
    }

    function cancelPendingGridRender() {
        gridRenderGeneration += 1;
        if (gridRenderFrame !== null) {
            if (typeof global.cancelAnimationFrame === 'function') global.cancelAnimationFrame(gridRenderFrame);
            else clearTimeout(gridRenderFrame);
        }
        gridRenderFrame = null;
        gridRenderState = null;
        if (gridImageLoader) gridImageLoader.disconnect();
    }

    function resolveGridImageSource(itemKey) {
        var d = load();
        var item = getLogicalItem(itemKey, d);
        if (!item) return '';
        var displayTheme = getItemDisplayTheme(d, item);
        var meta = d.themeMeta[displayTheme] || {};
        return imageToolsApi.resolvePreviewAsset(meta, d.previewImageQuality).src;
    }

    function showGridImageFallback(image) {
        if (!image || !image.closest) return;
        var card = image.closest('.tm-card');
        if (!card || !card.isConnected) return;
        card.classList.add('no-img', 'image-error');
        var slot = image.closest('.tm-card-preview-slot');
        if (slot) slot.style.display = 'none';
        var imageArea = card.querySelector('.tm-card-img');
        if (!imageArea || imageArea.querySelector('.tm-card-noimg')) return;
        var fallback = document.createElement('div');
        fallback.className = 'tm-card-noimg';
        var icon = document.createElement('i');
        icon.className = 'fa-solid fa-palette';
        var label = document.createElement('span');
        var name = card.querySelector('.tm-card-name');
        label.textContent = String(name ? name.textContent : '').slice(0, 6);
        fallback.appendChild(icon);
        fallback.appendChild(label);
        imageArea.insertBefore(fallback, imageArea.firstChild);
    }

    function resetGridImageLoader(area, generation) {
        var loaderOptions = {
            root: area,
            rootMargin: GRID_IMAGE_ROOT_MARGIN,
            maxConcurrent: 4,
            generation: generation,
            resolveSource: resolveGridImageSource,
            onError: showGridImageFallback,
        };
        if (!gridImageLoader) gridImageLoader = imageLoaderApi.createImageLoader(loaderOptions);
        else gridImageLoader.reset(loaderOptions);
    }

    function registerGridImages(images, state) {
        if (!gridImageLoader || !state || state.generation !== gridRenderGeneration) return;
        (images || []).forEach(function (image) {
            var hiddenSeries = image.closest && image.closest('.tm-series-preview-hidden:not(.is-expanded)');
            if (!hiddenSeries && state.eagerImagesRemaining > 0) {
                state.eagerImagesRemaining -= 1;
                gridImageLoader.loadNow(image, state.generation);
            } else {
                gridImageLoader.observe(image, state.generation);
            }
        });
    }

    function scheduleGridRenderChunk(state) {
        if (!state || state.generation !== gridRenderGeneration) return;
        var callback = function () {
            gridRenderFrame = null;
            appendGridRenderChunk(state);
        };
        gridRenderFrame = typeof global.requestAnimationFrame === 'function'
            ? global.requestAnimationFrame(callback)
            : setTimeout(callback, 0);
    }

    function gridUnitCardCount(unit) {
        return unit && unit.type === 'series' ? unit.items.length : 1;
    }

    function buildGridUnitHtml(unit, state) {
        return unit.type === 'series'
            ? buildSeriesBlockHtml(unit, state.data, state.currentTheme, state.view)
            : buildGridCardHtml(unit.item, state.data, state.currentTheme, state.view);
    }

    function registerRenderedCards(cards) {
        (cards || []).forEach(function (card) {
            if (card && card.dataset.key) renderedCardsByKey[card.dataset.key] = card;
        });
    }

    function finishGridRender(state) {
        if (!state || state.generation !== gridRenderGeneration) return;
        state.area.dataset.tmRenderComplete = 'true';
        state.area.dataset.tmRenderedCards = String(state.renderedCards);
        gridRenderState = null;
        gridRenderFrame = null;
        if (state.locateKey && locateCurrentOnRender) {
            var current = renderedCardsByKey[state.locateKey];
            if (current && current.isConnected) {
                locateCurrentOnRender = false;
                current.scrollIntoView({ block: 'center', inline: 'center', behavior: 'instant' });
            }
        }
        try {
            state.area.dispatchEvent(new CustomEvent('tm:grid-render-complete', {
                detail: { generation: state.generation, totalCards: state.renderedCards },
            }));
        } catch (e) {}
    }

    function appendGridRenderChunk(state) {
        if (!state || state.generation !== gridRenderGeneration ||
            document.getElementById('tm-grid-area') !== state.area || !state.area.isConnected) return;
        var html = '';
        var cardsInChunk = 0;
        var batchLimit = state.firstBatchDone ? GRID_RENDER_FOLLOWUP_BATCH_SIZE : GRID_RENDER_BATCH_SIZE;
        while (state.unitIndex < state.units.length && (cardsInChunk < batchLimit || cardsInChunk === 0)) {
            var unit = state.units[state.unitIndex++];
            html += buildGridUnitHtml(unit, state);
            cardsInChunk += gridUnitCardCount(unit);
        }
        if (state.generation !== gridRenderGeneration) return;
        var template = document.createElement('template');
        template.innerHTML = html;
        var cards = Array.from(template.content.querySelectorAll('.tm-card'));
        var images = Array.from(template.content.querySelectorAll('img[data-theme-key]'));
        state.grid.appendChild(template.content);
        if (state.generation !== gridRenderGeneration || document.getElementById('tm-grid-area') !== state.area) return;
        registerRenderedCards(cards);
        registerGridImages(images, state);
        state.renderedCards += cards.length;
        state.area.dataset.tmRenderedCards = String(state.renderedCards);
        if (!state.firstBatchDone) {
            state.firstBatchDone = true;
            state.area.dataset.tmFirstBatchReady = 'true';
            try {
                state.area.dispatchEvent(new CustomEvent('tm:grid-first-batch', {
                    detail: { generation: state.generation, renderedCards: state.renderedCards },
                }));
            } catch (e) {}
        }
        bindSeriesRailEvents(state.area);
        if (state.unitIndex < state.units.length) scheduleGridRenderChunk(state);
        else finishGridRender(state);
    }

    function updateActiveCardState(themeName) {
        var d = load();
        var view = buildLibraryView(d);
        var item = view.itemByThemeName[themeName] || null;
        if (gridRenderState) gridRenderState.currentTheme = themeName;
        function setCardActive(key, active) {
            var card = renderedCardsByKey[key];
            if (!card || !card.isConnected) return;
            card.classList.toggle('on', active);
            var badge = card.querySelector('.tm-badge-on');
            if (active && !batchMode && !badge) {
                badge = document.createElement('div');
                badge.className = 'tm-badge-on';
                badge.innerHTML = '<i class="fa-solid fa-check"></i>';
                var badgeHost = card.querySelector('.tm-card-img') || card.querySelector('.tm-card-text-actions');
                if (badgeHost) {
                    var menu = badgeHost.querySelector('.tm-card-menu');
                    if (menu) badgeHost.insertBefore(badge, menu);
                    else badgeHost.appendChild(badge);
                }
            } else if (!active && badge) badge.remove();
        }
        var nextKey = item ? item.key : '';
        if (renderedActiveItemKey && renderedActiveItemKey !== nextKey) setCardActive(renderedActiveItemKey, false);
        if (nextKey) setCardActive(nextKey, true);
        renderedActiveItemKey = item ? item.key : '';
    }

    function replaceRenderedCard(itemKey) {
        var oldCard = renderedCardsByKey[itemKey];
        if (!oldCard || !oldCard.isConnected) return false;
        var d = load();
        var view = buildLibraryView(d);
        var item = view.itemByKey[itemKey];
        if (!item) return false;
        var template = document.createElement('template');
        template.innerHTML = buildGridCardHtml(item, d, getCurrentThemeName(), view);
        var card = template.content.querySelector('.tm-card');
        if (!card) return false;
        var oldImage = oldCard.querySelector('img[data-theme-key]');
        if (oldImage && gridImageLoader) gridImageLoader.unobserve(oldImage);
        oldCard.replaceWith(card);
        renderedCardsByKey[itemKey] = card;
        var newImage = card.querySelector('img[data-theme-key]');
        if (newImage && gridImageLoader) gridImageLoader.observe(newImage, gridRenderGeneration);
        return true;
    }

    function refreshSingleItemCard(itemKey, effects) {
        effects = effects || {};
        var d = load();
        var mode = d.sortMode || 'name';
        var requiresLayout = effects.forceFull || effects.layout || effects.category || effects.name ||
            (effects.searchable && !!searchQuery) ||
            (effects.starred && mode === 'starred') ||
            (effects.recent && mode === 'recent') ||
            (effects.freq && mode === 'freq');
        if (requiresLayout || !replaceRenderedCard(itemKey)) renderGrid();
        else updateActiveCardState(getCurrentThemeName());
    }

    function bindGridDelegatedEvents(area) {
        if (!area || area._tmGridDelegatedBound) return;
        area.addEventListener('wheel', function () { locateCurrentOnRender = false; }, { passive: true });
        area.addEventListener('touchstart', function () { locateCurrentOnRender = false; }, { passive: true });
        area.addEventListener('click', function (event) {
            locateCurrentOnRender = false;
            var menu = event.target.closest('.tm-card-menu');
            if (menu && area.contains(menu)) {
                event.preventDefault();
                event.stopPropagation();
                if (!batchMode) openEditSheet(menu.dataset.key);
                return;
            }
            var card = event.target.closest('.tm-card');
            if (!card || !area.contains(card)) return;
            var key = card.dataset.key;
            var d = load();
            var item = getLogicalItem(key, d);
            if (!item) return;
            if (batchMode) {
                if (blockAmbiguousThemeItem(item)) return;
                if (batchDeleting) return;
                if (batchSelected.has(key)) batchSelected.delete(key); else batchSelected.add(key);
                var selected = batchSelected.has(key);
                var check = card.querySelector('.tm-card-check');
                if (check) check.classList.toggle('checked', selected);
                card.classList.toggle('batch-sel', selected);
                syncBatchActionState(load());
                return;
            }
            var themeName = getItemDisplayTheme(d, item);
            applyManualTheme(themeName, function (ok, reason, error) {
                if (ok) {
                    var dd = load();
                    var refreshedItem = getLogicalItem(item.key, dd);
                    var meta = refreshedItem ? getItemMetaForWrite(dd, refreshedItem) : null;
                    if (!meta) return;
                    meta.useCount = (meta.useCount || 0) + 1;
                    meta.lastUsed = Date.now();
                    save(dd);
                    toast('✅ 已应用：' + item.name);
                    refreshSingleItemCard(item.key, { recent: true, freq: true });
                    renderBottomStatus();
                    updateBtn();
                } else if (reason !== 'superseded') {
                    if (reason === 'incomplete') toast('主题尚未完整加载，不能安全切换', true);
                    else if (reason === 'load-failed') toast('主题加载失败：' + (error && error.message ? error.message : '已保留当前主题'), true);
                    else if (reason === 'state-verify-failed') toast('主题状态未能确认切换成功，未切换绑定背景', true);
                    else if (reason === 'verify-failed') toast('主题状态或视觉验证失败，未切换绑定背景', true);
                    else toast('切换失败，请重试', true);
                }
            });
        });
        area._tmGridDelegatedBound = true;
    }

    function renderGrid() {
        var area = document.getElementById('tm-grid-area');
        if (!area || !isThemePageActive()) return;
        cancelPendingGridRender();
        var generation = gridRenderGeneration;
        var batchArea = document.getElementById('tm-batch-area');
        var d = load();
        var view = buildLibraryView(d);
        var curTheme = getCurrentThemeName();
        captureSeriesScrollPositions(area);
        applyGridCardSize(d.gridCardSize);

        var sortedItems = sortItems(view.items, d.sortMode || 'name', d, view);
        var layout = buildSeriesLayoutUnits(d, sortedItems, curCat, searchQuery, view);
        var locateItem = locateCurrentOnRender ? view.itemByThemeName[curTheme] : null;
        if (locateItem) layout.units.some(function (unit) {
            if (unit.type !== 'series' || !unit.items.some(function (item) { return item.key === locateItem.key; })) return false;
            expandedSeriesId = unit.group.id;
            return true;
        });
        var metrics = getGridLayoutMetrics(area, d.gridCardSize);
        var units = d.noImageMode === true ? layout.units : alignSeriesUnitsForGrid(layout.units, metrics.columns);
        var list = layout.displayedItems;
        var inventoryWarning = themeNameConflicts.size > 0
            ? '<div class="tm-inventory-warning"><i class="fa-solid fa-triangle-exclamation"></i><span>酒馆主题库存中，以下每个名称都各出现多份：' +
                esc(formatThemeNameConflicts()) + '。常见原因是复制或重命名了主题 JSON，但文件内 name 没有改变。管理器已合并卡片显示；可以切换，请在酒馆主题目录清理重复文件后再编辑或删除。</span></div>'
            : '';
        syncSeriesCardWidth(area, d.gridCardSize);

        if (batchArea) {
            if (batchMode) {
                var disabledAttr = batchDeleting ? ' disabled' : '';
                var pairReady = batchSelected.size === 2 && getBatchSelectedKeys().every(function (key) {
                    var selectedItem = getLogicalItem(key, d);
                    return selectedItem && selectedItem.kind === 'theme';
                });
                batchArea.style.display = '';
                batchArea.innerHTML = '<div class="tm-batch-bar"><span class="tm-batch-info">' +
                (batchDeleting ? '正在删除 <b>' + batchSelected.size + '</b> 个…' : '已选 <b id="tm-batch-count">' + batchSelected.size + '</b> 个') +
                '</span>' +
                '<div class="tm-batch-divider"></div>' +
                '<div class="tm-batch-acts">' +
                '<button class="tm-batch-btn" id="tm-batch-selall"' + disabledAttr + '>全选</button>' +
                '<button class="tm-batch-btn" id="tm-batch-none"' + disabledAttr + '>取消</button>' +
                '<button class="tm-batch-btn" id="tm-batch-cat"' + disabledAttr + '><i class="fa-solid fa-folder"></i> 分类</button>' +
                '<button class="tm-batch-btn" id="tm-batch-star"' + disabledAttr + '><i class="fa-solid fa-star"></i> 收藏</button>' +
                '<button class="tm-batch-btn" id="tm-batch-tag"' + disabledAttr + '><i class="fa-solid fa-tag"></i> 标签</button>' +
                '<button class="tm-batch-btn tm-batch-day-night" id="tm-batch-day-night"' +
                (batchDeleting || !pairReady ? ' disabled' : '') +
                '><i class="fa-solid fa-circle-half-stroke"></i> 日夜</button>' +
                '<button class="tm-batch-btn tm-batch-series" id="tm-batch-series"' +
                (batchDeleting || batchSelected.size === 0 ? ' disabled' : '') +
                '><i class="fa-solid fa-layer-group"></i> 系列</button>' +
                '<button class="tm-batch-btn danger" id="tm-batch-delete"' + disabledAttr + '><i class="fa-solid fa-trash"></i> 删除</button>' +
                '</div></div>';
            } else {
                batchArea.style.display = 'none';
                batchArea.innerHTML = '';
            }
        }

        if (list.length === 0) {
            area.innerHTML = inventoryWarning + '<div class="tm-grid"></div><div class="tm-empty"><i class="fa-solid fa-palette"></i><span>' +
                (searchQuery ? '没有匹配「' + esc(searchQuery) + '」的主题' : (curCat !== '__all__' ? '该分类暂无主题' : (themeListLoadError || '没有找到主题，请点击底栏刷新按钮'))) +
                '</span></div>';
            renderedCardsByKey = Object.create(null);
            renderedActiveItemKey = '';
            area.dataset.tmRenderGeneration = String(generation);
            area.dataset.tmFirstBatchReady = 'true';
            area.dataset.tmRenderComplete = 'true';
            area.dataset.tmRenderedCards = '0';
        } else {
            area.innerHTML = inventoryWarning + '<div class="tm-grid"></div>';
            if (d.noImageMode === true) {
                if (gridImageLoader) gridImageLoader.disconnect();
            } else {
                resetGridImageLoader(area, generation);
            }
            renderedCardsByKey = Object.create(null);
            renderedActiveItemKey = (view.itemByThemeName[curTheme] || {}).key || '';
            area.dataset.tmRenderGeneration = String(generation);
            area.dataset.tmFirstBatchReady = 'false';
            area.dataset.tmRenderComplete = 'false';
            area.dataset.tmRenderedCards = '0';
            gridRenderState = {
                generation: generation,
                area: area,
                grid: area.querySelector('.tm-grid'),
                data: d,
                view: view,
                units: units,
                unitIndex: 0,
                renderedCards: 0,
                currentTheme: curTheme,
                locateKey: locateItem ? locateItem.key : '',
                firstBatchDone: false,
                eagerImagesRemaining: GRID_IMAGE_EAGER_COUNT,
            };
            appendGridRenderChunk(gridRenderState);
        }
        bindGridDelegatedEvents(area);

        // 事件绑定
        if (batchMode) {
            var batchRoot = batchArea || area;
            var selall = batchRoot.querySelector('#tm-batch-selall');
            var selnone = batchRoot.querySelector('#tm-batch-none');
            if (selall) selall.addEventListener('click', function () {
                batchSelected = new Set(list.map(function (item) { return item.key; }));
                renderGrid();
            });
            if (selnone) selnone.addEventListener('click', function () { batchSelected.clear(); renderGrid(); });

            var bcatBtn = batchRoot.querySelector('#tm-batch-cat');
            if (bcatBtn) bcatBtn.addEventListener('click', function () {
                if (batchSelected.size === 0) { toast('请先选择主题', true); return; }
                var dd = load(); var cats = dd.categories || [];
                if (cats.length === 0) { toast('还没有分类，请先在设置中添加', true); return; }
                openCategoryPicker({
                    title: '选择分类',
                    hint: '为已选 ' + batchSelected.size + ' 个美化设置分类',
                    onSelect: function (category) {
                        var currentData = load();
                        var selectedItems = getBatchSelectedKeys().map(function (key) { return getLogicalItem(key, currentData); }).filter(Boolean);
                        var selectedKeys = new Set();
                        selectedItems.forEach(function (item) { selectedKeys.add(item.key); });
                        var selectedGroups = Object.create(null);
                        selectedItems.forEach(function (item) {
                            var group = getSeriesForItem(currentData, item);
                            if (group) selectedGroups[group.id] = group;
                        });
                        var incompleteGroup = '';
                        getLogicalItems(currentData).some(function (item) {
                            var owner = getSeriesForItem(currentData, item);
                            if (!owner || !selectedGroups[owner.id] || selectedKeys.has(item.key)) return false;
                            incompleteGroup = owner.id;
                            return true;
                        });
                        if (incompleteGroup) {
                            toast('系列需要整组调整分类：请选中该系列全部成员，或点击系列标题修改展示分类', true);
                            return;
                        }
                        selectedItems.forEach(function (item) {
                            if (!getSeriesForItem(currentData, item)) getItemMetaForWrite(currentData, item).category = category;
                        });
                        Object.keys(selectedGroups).forEach(function (seriesId) {
                            seriesApi.setSeriesCategory(currentData, seriesId, category);
                        });
                        save(currentData);
                        toast('✅ 已将所选美化' + (Object.keys(selectedGroups).length ? '及系列' : '') + '移到「' + category + '」');
                        batchSelected.clear();
                        renderCatbar();
                        renderGrid();
                    },
                });
            });

            var bstarBtn = batchRoot.querySelector('#tm-batch-star');
            if (bstarBtn) bstarBtn.addEventListener('click', function () {
                if (batchSelected.size === 0) { toast('请先选择主题', true); return; }
                var dd = load();
                batchSelected.forEach(function (key) {
                    var item = getLogicalItem(key, dd);
                    if (item) {
                        var m = getItemMetaForWrite(dd, item);
                        m.starred = !m.starred;
                    }
                });
                save(dd); toast('⭐ 已切换收藏'); batchSelected.clear(); renderGrid();
            });

            var btagBtn = batchRoot.querySelector('#tm-batch-tag');
            if (btagBtn) btagBtn.addEventListener('click', function () {
                if (batchSelected.size === 0) { toast('请先选择主题', true); return; }
                openTagPicker({
                    title: '添加标签',
                    hint: '为已选 ' + batchSelected.size + ' 个美化添加标签；已有标签会保留',
                    selectedTags: [],
                    requireSelection: true,
                    allowClear: true,
                    onApply: function (tags) {
                        var dd = load();
                        batchSelected.forEach(function (key) {
                            var item = getLogicalItem(key, dd);
                            if (!item) return;
                            var meta = getItemMetaForWrite(dd, item);
                            if (!Array.isArray(meta.tags)) meta.tags = [];
                            tags.forEach(function (tag) { if (meta.tags.indexOf(tag) === -1) meta.tags.push(tag); });
                        });
                        save(dd);
                        toast('🏷️ 已为所选美化添加 ' + tags.length + ' 个标签');
                        batchSelected.clear();
                        renderGrid();
                    },
                    onClear: function () {
                        var dd = load();
                        batchSelected.forEach(function (key) {
                            var item = getLogicalItem(key, dd);
                            if (item) getItemMetaForWrite(dd, item).tags = [];
                        });
                        save(dd);
                        toast('已清除所选美化的标签');
                        batchSelected.clear();
                        renderGrid();
                    },
                });
            });

            var dayNightBtn = batchRoot.querySelector('#tm-batch-day-night');
            if (dayNightBtn) dayNightBtn.addEventListener('click', function () {
                if (batchSelected.size !== 2) {
                    toast('请选择两个尚未组合的美化', true);
                    return;
                }
                var dd = load();
                var selectedItems = getBatchSelectedKeys().map(function (key) { return getLogicalItem(key, dd); }).filter(Boolean);
                if (selectedItems.length !== 2 || selectedItems.some(function (item) { return item.kind !== 'theme'; })) {
                    toast('已组成日夜美化的卡片不能再次组合', true);
                    return;
                }
                openDayNightPairSheet(selectedItems[0], selectedItems[1]);
            });

            var seriesBtn = batchRoot.querySelector('#tm-batch-series');
            if (seriesBtn) seriesBtn.addEventListener('click', function () {
                var dd = load();
                var selectedItems = getBatchSelectedKeys().map(function (key) { return getLogicalItem(key, dd); }).filter(Boolean);
                if (selectedItems.length === 0) { toast('请先选择美化', true); return; }
                openSeriesBatchSheet(selectedItems);
            });

            var bdeleteBtn = batchRoot.querySelector('#tm-batch-delete');
            if (bdeleteBtn) bdeleteBtn.addEventListener('click', function () {
                if (batchDeleting) return;
                if (batchSelected.size === 0) { toast('请先选择主题', true); return; }

                var selectedItems = getBatchSelectedKeys().map(function (key) { return getLogicalItem(key, d); }).filter(Boolean);
                var names = expandItemThemeNames(selectedItems);
                var deletingNameSet = new Set(names);
                var currentTheme = getCurrentThemeName();
                var deletingCurrent = deletingNameSet.has(currentTheme);
                var fallbackTheme = deletingCurrent
                    ? stThemeList.find(function (name) { return !deletingNameSet.has(name); })
                    : '';
                if (deletingCurrent && !fallbackTheme) {
                    toast('当前美化也在所选范围内，请至少保留一个可切换的美化', true);
                    return;
                }

                var shownNames = selectedItems.slice(0, 8).map(function (item) { return '• ' + item.name; }).join('\n');
                if (selectedItems.length > 8) shownNames += '\n…另有 ' + (selectedItems.length - 8) + ' 个';
                var message = '确定删除选中的 ' + selectedItems.length + ' 个美化？\n\n' + shownNames +
                    '\n\n这会从 SillyTavern 主题列表中真实删除，无法通过管理器撤销。';
                if (deletingCurrent) message += '\n当前美化将先切换为「' + fallbackTheme + '」。';
                if (!confirm(message)) return;

                batchDeleting = true;
                renderGrid();

                function finishDeleteStart() {
                    deleteThemesEverywhere(names, function (ok, outcome) {
                        batchDeleting = false;
                        if (!ok) {
                            renderGrid();
                            toast('批量删除后无法完成验证，本地标注未清理，请刷新后确认', true);
                            return;
                        }

                        batchSelected = new Set(outcome.failed.map(function (failedItem) {
                            var logical = getLogicalItem(failedItem.name, load());
                            return logical ? logical.key : '';
                        }).filter(function (key) { return !!key; }));
                        renderGrid();
                        if (outcome.failed.length > 0) {
                            toast('已删除 ' + outcome.removed.length + ' 个；未删除 ' + outcome.failed.length + ' 个：' +
                                outcome.failed.map(function (item) { return item.name; }).join('、'), true);
                        } else {
                            toast('✅ 已删除 ' + outcome.removed.length + ' 个美化');
                        }
                    });
                }

                if (!deletingCurrent) {
                    finishDeleteStart();
                    return;
                }

                applyTheme(fallbackTheme, function (ok, reason) {
                    if (!ok) {
                        batchDeleting = false;
                        renderGrid();
                        if (reason !== 'superseded') toast('无法安全切换当前美化，批量删除已取消', true);
                        return;
                    }
                    renderGrid();
                    renderBottomStatus();
                    updateBtn();
                    finishDeleteStart();
                });
            });

        }
    }

    function seriesCategoryOptions(d, selected) {
        var html = '<option value=""' + (!selected ? ' selected' : '') + '>未分类</option>';
        (d.categories || []).forEach(function (category) {
            html += '<option value="' + esc(category) + '"' + (category === selected ? ' selected' : '') + '>' + esc(category) + '</option>';
        });
        html += '<option value="__new__">+ 新建分类…</option>';
        return html;
    }

    function resolveSeriesCategory(sheet, d) {
        var select = sheet.querySelector('.tm-series-category-select');
        if (!select) return '';
        var category = select.value;
        if (category !== '__new__') return category;
        var input = sheet.querySelector('.tm-series-new-category');
        category = input ? input.value.trim() : '';
        return category || null;
    }

    function bindSeriesCategorySelect(sheet) {
        var select = sheet.querySelector('.tm-series-category-select');
        var wrap = sheet.querySelector('.tm-series-new-category-wrap');
        if (!select || !wrap) return;
        function sync() { wrap.style.display = select.value === '__new__' ? '' : 'none'; }
        select.addEventListener('change', sync);
        sync();
    }

    function buildSeriesSelectedPreview(items) {
        return '<div class="tm-series-selected-list">' + items.map(function (item) {
            return '<span><i class="fa-solid ' + (item.kind === 'pair' ? 'fa-circle-half-stroke' : 'fa-palette') + '"></i>' + esc(item.name) + '</span>';
        }).join('') + '</div>';
    }

    function suggestedSeriesName(items) {
        var base = items && items[0] ? String(items[0].name || '').trim() : '';
        return (base ? base.slice(0, 48) + ' ' : '') + '系列';
    }

    function openSeriesBatchSheet(items) {
        if (!seriesApi) { toast('系列模块尚未就绪', true); return; }
        var d = load();
        var targets = [];
        var targetKeys = new Set();
        var ownerIds = [];
        var ownerIdSet = new Set();
        items.forEach(function (item) {
            var target = getItemTarget(item);
            var key = seriesApi.targetKey(target);
            if (key && !targetKeys.has(key)) { targetKeys.add(key); targets.push(target); }
            var owner = getSeriesForItem(d, item);
            if (owner && !ownerIdSet.has(owner.id)) { ownerIdSet.add(owner.id); ownerIds.push(owner.id); }
        });
        if (ownerIds.length > 1) {
            toast('所选美化分属不同系列，请先移出后再重新组合', true);
            return;
        }
        if (ownerIds.length === 1) {
            var ownerGroup = seriesApi.getSeries(d, ownerIds[0]);
            var membership = buildLibraryView(d).seriesMembership;
            var additions = targets.filter(function (target) { return !membership[seriesApi.targetKey(target)]; });
            var additionKeys = new Set(additions.map(function (target) { return seriesApi.targetKey(target); }));
            if (additions.length === 0) {
                openSeriesManageSheet(ownerGroup.id);
                return;
            }
            var additionItems = items.filter(function (item) {
                return additionKeys.has(seriesApi.targetKey(getItemTarget(item)));
            });
            var addSheet = createSheet([
                '<div class="tm-sheet-title"><i class="fa-solid fa-layer-group"></i>加入现有系列</div>',
                '<div class="tm-hint">以下美化会加入「' + esc(ownerGroup.name) + '」；已有成员不会重复添加。</div>',
                buildSeriesSelectedPreview(additionItems),
                '<div class="tm-edit-foot"><button class="tm-btn tm-btn-outline" id="tm-series-add-cancel">取消</button><button class="tm-btn tm-btn-safe" id="tm-series-add-save">确认加入</button></div>',
            ].join(''));
            addSheet.querySelector('#tm-series-add-cancel').addEventListener('click', function () { closeSheet(addSheet); });
            addSheet.querySelector('#tm-series-add-save').addEventListener('click', function () {
                var dd = load();
                var result = seriesApi.addMembers(dd, ownerGroup.id, additions);
                if (!result.ok) { toast('系列关系已变化，请刷新后重试', true); return; }
                save(dd);
                batchSelected.clear();
                closeSheet(addSheet);
                renderGrid();
                toast('✅ 已加入「' + ownerGroup.name + '」');
            });
            return;
        }

        var groups = seriesApi.listSeries(d);
        if (items.length < 2 && groups.length === 0) {
            toast('创建系列至少需要选择两个美化', true);
            return;
        }
        var commonCategory = '';
        if (curCat !== '__all__' && curCat !== '__uncategorized__') commonCategory = curCat;
        else if (items.length > 0) {
            var firstCategory = getItemMeta(d, items[0]).category || '';
            if (items.every(function (item) { return (getItemMeta(d, item).category || '') === firstCategory; })) commonCategory = firstCategory;
        }
        var operationItems = (items.length >= 2 ? [{ value: 'new', label: '创建新系列', hint: '使用当前选择创建一个新系列', icon: 'fa-plus' }] : []).concat(groups.map(function (group) {
            return { value: group.id, label: '加入「' + group.name + '」', hint: group.members.length + ' 款美化', icon: 'fa-layer-group' };
        }));
        var operationValue = items.length < 2 && groups.length > 0 ? groups[0].id : 'new';
        var sheet = createSheet([
            '<div class="tm-sheet-title"><i class="fa-solid fa-layer-group"></i>保存为系列</div>',
            '<div class="tm-hint tm-series-hint">系列只收纳展示关系，不会复制或修改真实美化；解散系列也不会删除成员。成员顺序始终跟随当前排序。</div>',
            buildSeriesSelectedPreview(items),
            '<div class="tm-field"><label>操作</label><button type="button" class="tm-picker-trigger" id="tm-series-operation"><span class="tm-picker-trigger-icon"><i class="fa-solid fa-layer-group"></i></span><span class="tm-picker-trigger-copy"><strong></strong><small></small></span><i class="fa-solid fa-chevron-right tm-picker-trigger-chevron"></i></button></div>',
            '<div id="tm-series-create-fields">' +
            '<div class="tm-field"><label>系列名称</label><input type="text" id="tm-series-name" maxlength="80" value="' + esc(suggestedSeriesName(items)) + '" /></div>' +
            '<div class="tm-field"><label>展示分类</label><select class="tm-series-category-select">' + seriesCategoryOptions(d, commonCategory) + '</select></div>' +
            '<div class="tm-field tm-series-new-category-wrap" style="display:none"><label>新分类名称</label><input type="text" class="tm-series-new-category" maxlength="40" /></div>' +
            '</div>',
            '<div class="tm-edit-foot"><button class="tm-btn tm-btn-outline" id="tm-series-create-cancel">取消</button><button class="tm-btn tm-btn-safe" id="tm-series-create-save">保存系列</button></div>',
        ].join(''));
        var operation = sheet.querySelector('#tm-series-operation');
        var createFields = sheet.querySelector('#tm-series-create-fields');
        var saveButton = sheet.querySelector('#tm-series-create-save');
        function syncOperation() {
            var creating = operationValue === 'new';
            var selectedOperation = operationItems.find(function (item) { return item.value === operationValue; }) || operationItems[0];
            if (selectedOperation) {
                operation.querySelector('strong').textContent = selectedOperation.label;
                operation.querySelector('small').textContent = selectedOperation.hint;
            }
            createFields.style.display = creating ? '' : 'none';
            saveButton.textContent = creating ? '保存系列' : '确认加入';
        }
        operation.addEventListener('click', function () {
            openChoicePicker({
                title: '选择系列操作',
                icon: 'fa-layer-group',
                items: operationItems,
                selected: operationValue,
                searchPlaceholder: '搜索系列…',
                emptySearchText: '没有匹配的系列',
                onSelect: function (value) { operationValue = value; syncOperation(); },
            });
        });
        syncOperation();
        bindSeriesCategorySelect(sheet);
        sheet.querySelector('#tm-series-create-cancel').addEventListener('click', function () { closeSheet(sheet); });
        saveButton.addEventListener('click', function () {
            var dd = load();
            var result;
            if (operationValue === 'new') {
                if (targets.length < 2) { toast('创建系列至少需要两个美化', true); return; }
                var name = sheet.querySelector('#tm-series-name').value.trim();
                if (!name) { toast('请输入系列名称', true); return; }
                if (seriesApi.listSeries(dd).some(function (group) { return group.name === name; })) {
                    toast('已有同名系列，请换一个名称', true);
                    return;
                }
                var category = resolveSeriesCategory(sheet, dd);
                if (category === null) { toast('请输入新分类名称', true); return; }
                result = seriesApi.createSeries(dd, { name: name, category: category, members: targets });
            } else {
                result = seriesApi.addMembers(dd, operationValue, targets);
            }
            if (!result.ok) {
                toast(result.reason === 'already-series' ? '其中一个美化已经属于其他系列' : '无法保存系列，请重试', true);
                return;
            }
            if (category && dd.categories.indexOf(category) === -1) dd.categories.push(category);
            save(dd);
            batchSelected.clear();
            closeSheet(sheet);
            renderCatbar();
            renderGrid();
            toast(operationValue === 'new' ? '✅ 已创建系列' : '✅ 已加入系列');
        });
    }

    function getSeriesMemberView(d, target) {
        var view = buildLibraryView(d);
        var item = target.kind === 'day-night'
            ? view.pairById[target.pairId]
            : view.itemByThemeName[target.themeName];
        if (item) return { name: item.name, kind: item.kind, available: true };
        return {
            name: target.kind === 'day-night' ? ('日夜组合 ' + target.pairId) : target.themeName,
            kind: target.kind === 'day-night' ? 'pair' : 'theme',
            available: false,
        };
    }

    function openSeriesManageSheet(seriesId) {
        if (!seriesApi) return;
        var d = load();
        var group = seriesApi.getSeries(d, seriesId);
        if (!group) { toast('这个系列已经不存在', true); renderGrid(); return; }
        var memberHtml = group.members.map(function (target, index) {
            var view = getSeriesMemberView(d, target);
            return '<div class="tm-series-member-row" data-member-index="' + index + '">' +
                '<i class="fa-solid ' + (view.kind === 'pair' ? 'fa-circle-half-stroke' : 'fa-palette') + '"></i>' +
                '<div><strong>' + esc(view.name) + '</strong>' + (view.available ? '' : '<small>当前主题列表中不可用</small>') + '</div>' +
                '<button type="button" class="tm-btn-sm tm-series-member-remove" data-member-index="' + index + '" title="移出系列"><i class="fa-solid fa-xmark"></i></button></div>';
        }).join('');
        var sheet = createSheet([
            '<div class="tm-sheet-title"><i class="fa-solid fa-layer-group"></i>管理系列</div>',
            '<div class="tm-field"><label>系列名称</label><input type="text" id="tm-series-manage-name" maxlength="80" value="' + esc(group.name) + '" /></div>',
            '<div class="tm-field"><label>展示分类</label><select class="tm-series-category-select">' + seriesCategoryOptions(d, group.category) + '</select></div>',
            '<div class="tm-field tm-series-new-category-wrap" style="display:none"><label>新分类名称</label><input type="text" class="tm-series-new-category" maxlength="40" /></div>',
            '<div class="tm-sec-title">成员 · ' + group.members.length + ' 款</div>',
            '<div class="tm-hint">这里只管理收纳关系；移出、解散都不会删除真实美化。</div>',
            '<div class="tm-series-member-list">' + memberHtml + '</div>',
            '<div class="tm-edit-foot tm-series-manage-actions"><button class="tm-btn tm-btn-danger" id="tm-series-dissolve">解散系列</button><span></span><button class="tm-btn tm-btn-outline" id="tm-series-manage-cancel">取消</button><button class="tm-btn tm-btn-safe" id="tm-series-manage-save">保存修改</button></div>',
        ].join(''));
        bindSeriesCategorySelect(sheet);
        sheet.querySelector('#tm-series-manage-cancel').addEventListener('click', function () { closeSheet(sheet); });
        sheet.querySelector('#tm-series-manage-save').addEventListener('click', function () {
            var dd = load();
            var current = seriesApi.getSeries(dd, seriesId);
            if (!current) { closeSheet(sheet); toast('这个系列已经不存在', true); renderGrid(); return; }
            var name = sheet.querySelector('#tm-series-manage-name').value.trim();
            if (!name) { toast('请输入系列名称', true); return; }
            if (seriesApi.listSeries(dd).some(function (other) { return other.id !== seriesId && other.name === name; })) {
                toast('已有同名系列，请换一个名称', true);
                return;
            }
            var category = resolveSeriesCategory(sheet, dd);
            if (category === null) { toast('请输入新分类名称', true); return; }
            seriesApi.renameSeries(dd, seriesId, name);
            seriesApi.setSeriesCategory(dd, seriesId, category);
            if (category && dd.categories.indexOf(category) === -1) dd.categories.push(category);
            save(dd);
            closeSheet(sheet);
            renderCatbar();
            renderGrid();
            toast('✅ 已保存系列');
        });
        sheet.querySelector('#tm-series-dissolve').addEventListener('click', function () {
            if (!confirm('解散系列「' + group.name + '」？\n所有真实美化都会保留。')) return;
            var dd = load();
            seriesApi.dissolveSeries(dd, seriesId);
            save(dd);
            if (expandedSeriesId === seriesId) expandedSeriesId = '';
            closeSheet(sheet);
            renderGrid();
            toast('已解散系列，美化均已保留');
        });
        sheet.querySelectorAll('.tm-series-member-remove').forEach(function (button) {
            button.addEventListener('click', function () {
                var index = parseInt(button.dataset.memberIndex, 10);
                var target = group.members[index];
                if (!target) return;
                if (group.members.length <= 2 && !confirm('移出后系列将自动解散，所有真实美化仍会保留。是否继续？')) return;
                var dd = load();
                var result = seriesApi.removeMember(dd, seriesId, target);
                if (!result.ok) { toast('成员关系已变化，请刷新后重试', true); return; }
                save(dd);
                closeSheet(sheet);
                if (result.dissolved) {
                    if (expandedSeriesId === seriesId) expandedSeriesId = '';
                    renderGrid();
                    toast('系列已自动解散，美化均已保留');
                } else {
                    renderGrid();
                    toast('已移出系列');
                    openSeriesManageSheet(seriesId);
                }
            });
        });
    }

    function openDayNightPairSheet(firstItem, secondItem) {
        if (!pairsApi || !firstItem || !secondItem || firstItem.kind !== 'theme' || secondItem.kind !== 'theme') return;
        var d = load();
        var dayTheme = firstItem.themeName;
        var nightTheme = secondItem.themeName;
        var suggestedName = pairsApi.suggestPairName(dayTheme, nightTheme);

        function optionHtml(selected) {
            return [firstItem, secondItem].map(function (item) {
                return '<option value="' + esc(item.themeName) + '"' + (item.themeName === selected ? ' selected' : '') + '>' +
                    esc(item.name) + '</option>';
            }).join('');
        }

        var sheet = createSheet([
            '<div class="tm-sheet-title"><i class="fa-solid fa-circle-half-stroke"></i>组成日夜美化</div>',
            '<div class="tm-hint tm-day-night-hint">保存后两张卡片会合并成一个美化；系统浅色模式使用日间版，深色模式使用夜间版。</div>',
            '<div class="tm-field"><label>合并后的名称</label><input type="text" id="tm-pair-name" maxlength="80" value="' + esc(suggestedName) + '" placeholder="例如：春日花园" /></div>',
            '<div class="tm-day-night-assign">',
            '<div class="tm-day-night-choice is-day"><div class="tm-day-night-choice-label"><i class="fa-solid fa-sun"></i><span>日间版本</span></div><select id="tm-pair-day">' + optionHtml(dayTheme) + '</select></div>',
            '<button type="button" class="tm-day-night-swap" id="tm-pair-swap" title="交换日夜" aria-label="交换日间和夜间版本">' +
            '<svg class="tm-day-night-swap-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 7h12m0 0-3-3m3 3-3 3M18 17H6m0 0 3 3m-3-3 3-3"></path></svg></button>',
            '<div class="tm-day-night-choice is-night"><div class="tm-day-night-choice-label"><i class="fa-solid fa-moon"></i><span>夜间版本</span></div><select id="tm-pair-night">' + optionHtml(nightTheme) + '</select></div>',
            '</div>',
            '<div class="tm-edit-foot"><button class="tm-btn tm-btn-outline" id="tm-pair-cancel">取消</button><button class="tm-btn tm-btn-safe" id="tm-pair-save">保存组合</button></div>',
        ].join(''));

        var daySelect = sheet.querySelector('#tm-pair-day');
        var nightSelect = sheet.querySelector('#tm-pair-night');
        function keepDistinct(changed) {
            if (daySelect.value !== nightSelect.value) return;
            var other = changed === daySelect ? nightSelect : daySelect;
            other.value = changed.value === firstItem.themeName ? secondItem.themeName : firstItem.themeName;
        }
        daySelect.addEventListener('change', function () { keepDistinct(daySelect); });
        nightSelect.addEventListener('change', function () { keepDistinct(nightSelect); });
        sheet.querySelector('#tm-pair-swap').addEventListener('click', function () {
            var previous = daySelect.value;
            daySelect.value = nightSelect.value;
            nightSelect.value = previous;
        });
        sheet.querySelector('#tm-pair-cancel').addEventListener('click', function () { closeSheet(sheet); });
        sheet.querySelector('#tm-pair-save').addEventListener('click', function () {
            var name = sheet.querySelector('#tm-pair-name').value.trim();
            if (!name) { toast('请输入合并后的名称', true); return; }
            if (daySelect.value === nightSelect.value) { toast('日间版和夜间版不能是同一个美化', true); return; }
            var currentData = load();
            var duplicate = getLogicalItems(currentData).some(function (item) {
                return item.key !== firstItem.key && item.key !== secondItem.key && item.name === name;
            });
            if (duplicate) { toast('已有同名美化，请换一个名称', true); return; }
            if (seriesApi) {
                var firstSeries = seriesApi.findSeriesByTarget(currentData, { kind: 'theme', themeName: daySelect.value });
                var secondSeries = seriesApi.findSeriesByTarget(currentData, { kind: 'theme', themeName: nightSelect.value });
                if (firstSeries && secondSeries && firstSeries.id !== secondSeries.id) {
                    toast('这两个美化分属不同系列，请先移出其中一个再组成日夜美化', true);
                    return;
                }
            }
            var result = pairsApi.createPair(currentData, {
                name: name,
                dayTheme: daySelect.value,
                nightTheme: nightSelect.value,
            });
            if (!result.ok) {
                toast(result.reason === 'already-paired' ? '其中一个美化已经属于日夜组合' : '无法保存日夜组合', true);
                return;
            }
            if (seriesApi) {
                var seriesMerge = seriesApi.mergeThemeTargetsIntoPair(
                    currentData,
                    [result.pair.dayTheme, result.pair.nightTheme],
                    result.pair.id
                );
                if (!seriesMerge.ok) {
                    pairsApi.dissolvePair(currentData, result.pair.id);
                    toast('系列关系发生变化，日夜组合未保存，请重试', true);
                    return;
                }
            }
            if (bindingsApi) {
                bindingsApi.mergeThemeReferencesIntoPair(
                    currentData,
                    [result.pair.dayTheme, result.pair.nightTheme],
                    result.pair.id
                );
            }
            save(currentData);
            batchSelected.clear();
            closeSheet(sheet);
            renderCatbar();
            renderGrid();
            renderBottomStatus();
            toast('☀️🌙 已合并为「' + name + '」');
        });
    }

    function dissolveDayNightPair(pairId, sheet) {
        var d = load();
        var pair = pairsApi.getPair(d, pairId);
        if (!pair) return;
        var preferredTheme = pairsApi.getVariantTheme(d, pairId, getPreferredPairVariant(pairId));
        var replacementTheme = stThemeList.indexOf(preferredTheme) !== -1
            ? preferredTheme
            : (stThemeList.indexOf(pair.dayTheme) !== -1 ? pair.dayTheme : (stThemeList.indexOf(pair.nightTheme) !== -1 ? pair.nightTheme : ''));
        if (seriesApi) {
            var seriesResult = seriesApi.replacePairReference(d, pairId, [pair.dayTheme, pair.nightTheme]);
            if (!seriesResult.ok) {
                toast('这组日夜美化与其他系列存在成员冲突，请先整理系列关系后再解除', true);
                return;
            }
        }
        pairsApi.dissolvePair(d, pairId);
        if (bindingsApi) bindingsApi.replacePairReferences(d, pairId, replacementTheme);
        save(d);
        if (sheet) closeSheet(sheet);
        renderCatbar();
        renderGrid();
        renderBottomStatus();
        toast('已解除日夜组合，两个美化均已保留');
    }

    function deleteDayNightPair(pairId, sheet) {
        var d = load();
        var pair = pairsApi.getPair(d, pairId);
        if (!pair) return;
        var names = [pair.dayTheme, pair.nightTheme].filter(function (name) {
            return stThemeList.indexOf(name) !== -1;
        });
        if (names.length === 0) {
            dissolveDayNightPair(pairId, sheet);
            return;
        }
        var currentTheme = getCurrentThemeName();
        var deletingCurrent = names.indexOf(currentTheme) !== -1;
        var fallbackTheme = deletingCurrent
            ? stThemeList.find(function (name) { return names.indexOf(name) === -1; })
            : '';
        if (deletingCurrent && !fallbackTheme) {
            toast('请至少保留一个可切换的美化后再删除这组日夜美化', true);
            return;
        }
        if (sheet) closeSheet(sheet);

        function startDelete() {
            deleteThemesEverywhere(names, function (ok, outcome) {
                if (!ok) {
                    toast('删除后无法完成验证，日夜关系与本地标注已保留', true);
                    return;
                }
                if (outcome.failed.length > 0) {
                    toast('已删除 ' + outcome.removed.length + ' 个；未删除：' +
                        outcome.failed.map(function (item) { return item.name; }).join('、'), true);
                } else {
                    toast('已删除日夜组合及两个真实美化');
                }
            });
        }

        if (!deletingCurrent) {
            startDelete();
            return;
        }
        applyTheme(fallbackTheme, function (ok, reason) {
            if (!ok) {
                if (reason !== 'superseded') toast('无法安全切换当前美化，删除已取消', true);
                return;
            }
            startDelete();
        });
    }

    function openDayNightDeleteSheet(pairId) {
        var d = load();
        var pair = pairsApi.getPair(d, pairId);
        if (!pair) return;
        var sheet = createSheet([
            '<div class="tm-sheet-title"><i class="fa-solid fa-circle-half-stroke"></i>管理日夜组合</div>',
            '<div class="tm-hint">「解除组合」只拆开关系并保留两个真实美化；「删除整组」会在 SillyTavern 中真实删除日间版和夜间版。</div>',
            '<div class="tm-day-night-members"><span><i class="fa-solid fa-sun"></i>' + esc(pair.dayTheme) + '</span><span><i class="fa-solid fa-moon"></i>' + esc(pair.nightTheme) + '</span></div>',
            '<div class="tm-edit-foot tm-day-night-delete-actions"><button class="tm-btn tm-btn-outline" id="tm-pair-manage-cancel">取消</button><button class="tm-btn tm-btn-outline" id="tm-pair-dissolve">解除组合</button><button class="tm-btn tm-btn-danger" id="tm-pair-delete-all">删除整组</button></div>',
        ].join(''));
        sheet.querySelector('#tm-pair-manage-cancel').addEventListener('click', function () { closeSheet(sheet); });
        sheet.querySelector('#tm-pair-dissolve').addEventListener('click', function () {
            dissolveDayNightPair(pairId, sheet);
        });
        sheet.querySelector('#tm-pair-delete-all').addEventListener('click', function () {
            deleteDayNightPair(pairId, sheet);
        });
    }

    var themeShowcaseApi = null;
    function openThemeShowcase() {
        if (!getCurrentThemeName()) { toast('请先选择并应用一个美化', true); return; }
        if (themeRuntime.isApplyInProgress()) { toast('美化仍在切换，请稍后再试', true); return; }
        if (themeShowcaseApi && themeShowcaseApi.isBusy()) { toast('美化展示正在生成，请稍候', true); return; }
        // Resolve dirty editor drafts before updating the persisted cover behind an editor.
        var overlay = document.querySelector('.tm-overlay');
        if (overlay && !uiSheetsApi.requestCloseAll(overlay, 'showcase')) return;
        if (!themeShowcaseApi) themeShowcaseApi = modules.createThemeShowcase({
            getThemeName: getCurrentThemeName,
            isThemeApplying: function () { return themeRuntime.isApplyInProgress(); },
            load: load, ensureMeta: ensureMeta, save: save,
            hasTheme: function (name) { return !!getLogicalItem(name, load()); },
            makeThumbnail: function (image) { return new Promise(function (resolve) { makeResponsiveThumb(image, resolve); }); },
            uploadImage: function (image) { return new Promise(function (resolve, reject) { uploadImage(image, function (error, url) { if (error) reject(error); else resolve(url); }); }); },
            onSaved: function () { renderGrid(); renderBottomStatus(); },
        });
        var sheet = createSheet('<div class="tm-sheet-title"><i class="fa-solid fa-camera"></i>美化展示</div>' +
            '<div class="tm-hint">截取当前聊天最近一组 User / 角色消息，自动替换当前美化封面。长消息最多展示前 900px；日夜组合只更新当前版本。截图会包含消息正文和头像，分享美化包时会随封面导出。</div>' +
            '<div class="tm-hint" data-showcase-status role="status" aria-live="polite">正在准备截图…</div>' +
            '<div data-showcase-preview></div><div class="tm-edit-foot"><button type="button" class="tm-btn tm-btn-outline" data-showcase-close disabled>关闭</button><button type="button" class="tm-btn tm-btn-safe" data-showcase-retry disabled>重新生成</button></div>');
        var close = sheet.querySelector('[data-showcase-close]'), retry = sheet.querySelector('[data-showcase-retry]');
        var status = sheet.querySelector('[data-showcase-status]');
        var running = false;
        uiSheetsApi.setBeforeClose(sheet, function () { if (running) { toast('请等待展示封面保存完成', true); return false; } return true; });
        close.addEventListener('click', function () { closeSheet(sheet); });
        retry.addEventListener('click', generate);
        async function generate() {
            if (running) return;
            running = true; close.disabled = retry.disabled = true;
            try {
                var result = await themeShowcaseApi.captureAndSave(function (message) { status.textContent = message; });
                status.textContent = '已设为「' + result.themeName + '」的展示封面';
                sheet.querySelector('[data-showcase-preview]').innerHTML = '<img src="' + esc(result.imageData) + '" alt="当前美化的 User 与角色消息展示" style="display:block;width:100%;height:auto;border-radius:8px;margin-top:12px">';
                toast('美化展示已保存为封面');
            } catch (error) {
                status.textContent = '生成失败：' + (error.message || '未知错误') + '。原封面已保留。';
                toast('美化展示生成失败，请查看提示', true);
                console.warn('[美化管理] 美化展示失败:', error);
            } finally { running = false; close.disabled = retry.disabled = false; close.focus(); }
        }
        generate();
    }


    // ── 底栏状态 ─────────────────────────────────────────────
    function renderBottomStatus() {
        var el = document.getElementById('tm-bottom-status'); if (!el) return;
        var curTheme = getCurrentThemeName();
        var showcaseButton = document.getElementById('tm-showcase');
        if (showcaseButton) showcaseButton.disabled = !curTheme || themeRuntime.isApplyInProgress();
        var dotClass = curTheme ? 'green' : 'gray';
        var item = curTheme ? getLogicalItem(curTheme, load()) : null;
        var text = item ? item.name : (curTheme || '未选择主题');
        el.innerHTML = '<div class="tm-status-dot ' + dotClass + '"></div><span class="tm-status-text">' + esc(text) + '</span>';
    }

    function syncAvatarImportIndicator(importState) {
        if (!importState && avatarPageController && typeof avatarPageController.getImportState === 'function') importState = avatarPageController.getImportState();
        importState = importState || { phase: 'idle', total: 0, processed: 0 };
        var active = importState.phase === 'running';
        var targets = Array.prototype.slice.call(document.querySelectorAll('[data-tm-page-target="avatars"],#tm-avatar-add'));
        var switcher = document.getElementById('tm-page-switcher-button');
        if (switcher && (!appShellController || appShellController.getActivePage() === 'avatars')) targets.push(switcher);
        targets.forEach(function (element) {
            element.classList.toggle('tm-avatar-import-active', active);
            if (active) element.setAttribute('data-avatar-import-progress', importState.processed + '/' + importState.total);
            else element.removeAttribute('data-avatar-import-progress');
        });
        var addButton = document.getElementById('tm-avatar-add');
        if (addButton) {
            addButton.disabled = active || avatarTransferApi && avatarTransferApi.getState().busy || !avatarCoordinator || !avatarCoordinator.canMutate();
            addButton.title = active ? '头像正在后台导入 ' + importState.processed + ' / ' + importState.total : '添加头像';
            addButton.setAttribute('aria-label', addButton.title);
        }
    }

    function renderAvatarBottomStatus() {
        if (!avatarPageController) return;
        var character = avatarPageController.getNativeStatus('character');
        var user = avatarPageController.getNativeStatus('user');
        var button = document.getElementById('tm-avatar-global');
        if (button) {
            button.disabled = !user.targetKey && !character.targetKey;
            button.title = button.disabled ? (user.reason || character.reason || '头像解绑当前不可用') : '头像解绑';
        }
    }

    function openAvatarGlobalMenu() {
        if (!avatarRuntime || !avatarPageController || !uiSheetsApi) return;
        var user = avatarPageController.getNativeStatus('user');
        var character = avatarPageController.getNativeStatus('character');
        Promise.all([
            avatarRuntime.getApplicationScopes('user'),
            avatarRuntime.getApplicationScopes('character'),
            avatarRuntime.getAvatarBindingRecoverySummary(),
        ]).then(function (parts) {
            var states = { user: parts[0], character: parts[1] };
            var recovery = parts[2];
            function item(kind, scope, icon, label) {
                var state = states[kind] && states[kind].scopes && states[kind].scopes[scope] || {};
                var bound = Boolean(state.binding);
                var hint = bound
                    ? (scope === 'theme' ? '已绑定 ' + Number(state.count || 1) + ' 张头像' : '当前有绑定')
                    : '当前无绑定';
                return '<button type="button" class="tm-action-dialog-item" data-avatar-global-action="clear" data-avatar-kind="' + kind + '" data-avatar-scope="' + scope + '"' + (bound ? '' : ' disabled') + '><i class="fa-solid ' + icon + '"></i><span><strong>' + esc(label) + '</strong><small>' + esc(hint) + '</small></span></button>';
            }
            function group(kind, icon, label) {
                return '<div class="tm-avatar-unbind-group-title"><i class="fa-solid ' + icon + '"></i><span>' + esc(label) + '</span></div>' +
                    item(kind, 'chat', 'fa-comments', '清除当前聊天绑定') +
                    item(kind, 'theme', 'fa-palette', '清除当前美化绑定') +
                    item(kind, 'global', 'fa-globe', '清除全局绑定');
            }
            var characterLabel = character.targetKey ? (character.label || '当前角色') : '当前角色不可用';
            var menu = uiSheetsApi.createActionDialog('<div class="tm-action-dialog-title"><i class="fa-solid fa-eraser"></i>头像解绑</div><div class="tm-action-dialog-list">' +
                group('user', 'fa-user', 'User') +
                '<div class="tm-action-dialog-divider"></div>' +
                group('character', 'fa-address-card', characterLabel) +
                '<div class="tm-avatar-unbind-danger"><button type="button" class="tm-action-dialog-item is-danger" data-avatar-global-action="recover"' + (recovery.total ? '' : ' disabled') + '><i class="fa-solid fa-rotate-left"></i><span><strong>全部解绑并恢复原头像</strong><small>清除两者在所有聊天、美化和全局中的绑定</small></span></button></div>' +
                '</div>');
            menu.addEventListener('click', function (event) {
                var actionButton = event.target.closest('[data-avatar-global-action]');
                if (!actionButton || actionButton.disabled) return;
                var action = actionButton.dataset.avatarGlobalAction;
                if (action === 'recover') {
                    var targetsLabel = character.targetKey ? '当前 User 与「' + characterLabel + '」' : '当前 User';
                    if (!confirm('确认全部解绑并恢复原头像？\n这会清除' + targetsLabel + '在所有聊天、所有美化和全局中的头像绑定。\n头像库图片、SillyTavern 原图和原头像调整数据都会保留。')) return;
                    closeSheet(menu);
                    avatarRuntime.clearAllAvatarBindings().then(function (result) {
                        toast('已恢复原头像，共解除 ' + result.bindingsCleared + ' 项绑定');
                        return avatarPageController.refresh();
                    }).catch(function (error) { toast(error.message || '恢复原头像失败', true); });
                    return;
                }
                var kind = actionButton.dataset.avatarKind === 'character' ? 'character' : 'user';
                var scope = actionButton.dataset.avatarScope;
                closeSheet(menu);
                avatarRuntime.clearApplicationScope(kind, scope).then(function () {
                    var targetLabel = kind === 'character' ? characterLabel : 'User';
                    var scopeLabel = scope === 'chat' ? '当前聊天' : (scope === 'theme' ? '当前美化' : '全局');
                    toast('已清除' + targetLabel + '的' + scopeLabel + '绑定');
                    return avatarPageController.refresh();
                }).catch(function (error) { toast(error.message || '解除头像绑定失败', true); });
            });
        }).catch(function (error) { toast(error.message || '头像绑定读取失败', true); });
    }

    // ── 角色 / 聊天绑定 ──────────────────────────────────────
    function openBindingSheet(itemRef, onChange) {
        if (!bindingController || !bindingsApi) {
            toast('绑定模块尚未就绪', true);
            return;
        }

        var data = load();
        var item = getLogicalItem(itemRef, data);
        if (!item) {
            toast('找不到要绑定的美化', true);
            return;
        }
        var target = getItemTarget(item);
        var current = bindingController.getCurrentState();
        var info = current.context;

        function bindingLabel(record) {
            if (!record) return '';
            var recordTarget = bindingsApi.getTarget(record);
            if (!recordTarget) return '';
            if (recordTarget.kind === 'day-night') {
                var pair = pairsApi.getPair(load(), recordTarget.pairId);
                return pair ? pair.name : '已失效的日夜组合';
            }
            return recordTarget.themeName || '';
        }

        function buildBindingCard(scope, title, icon, available, label, record) {
            var boundTarget = record ? bindingsApi.getTarget(record) : null;
            var boundLabel = bindingLabel(record);
            var isThisTheme = bindingsApi.targetsEqual(boundTarget, target);
            var status = boundLabel
                ? ('已绑定：' + esc(boundLabel))
                : '尚未绑定';
            var actionLabel = boundLabel
                ? (isThisTheme ? '已绑定此美化' : '改绑为此美化')
                : '绑定此美化';
            var priorityOn = current.resolution.scope === scope;
            return '<div class="tm-binding-card' + (priorityOn ? ' is-active' : '') + '">' +
                '<div class="tm-binding-head"><i class="fa-solid ' + icon + '"></i><div><strong>' + title + '</strong>' +
                '<small>' + (available ? esc(label) : (scope === 'chat' ? '当前没有可绑定的聊天窗口' : '群聊或主页不提供单角色绑定')) + '</small></div>' +
                (priorityOn ? '<span>当前生效</span>' : '') + '</div>' +
                '<div class="tm-binding-status">' + status + '</div>' +
                '<div class="tm-binding-actions">' +
                '<button class="tm-btn tm-btn-safe" data-binding-action="bind" data-binding-scope="' + scope + '"' +
                (!available || isThisTheme ? ' disabled' : '') + '>' + actionLabel + '</button>' +
                (boundLabel ? '<button class="tm-btn tm-btn-outline" data-binding-action="clear" data-binding-scope="' + scope + '">解除绑定</button>' : '') +
                '</div></div>';
        }

        var sheet = createSheet([
            '<div class="tm-sheet-title"><i class="fa-solid fa-link"></i>绑定：' + esc(item.name) + '</div>',
            '<div class="tm-hint tm-binding-hint">切换聊天时自动应用；聊天绑定优先于角色绑定，离开绑定范围后恢复最后一次手动选择的美化。</div>',
            buildBindingCard(
                'character',
                '当前角色卡',
                'fa-user',
                !info.isGroup && !!info.characterKey,
                info.characterLabel || info.characterKey,
                current.character
            ),
            buildBindingCard(
                'chat',
                '当前聊天窗口',
                'fa-message',
                !!(info.chatKey && info.chatId),
                info.chatLabel || info.chatId,
                current.chat
            ),
            '<div class="tm-edit-foot"><button class="tm-btn tm-btn-outline" id="tm-binding-close">关闭</button></div>',
        ].join(''));

        sheet.querySelector('#tm-binding-close').addEventListener('click', function () {
            closeSheet(sheet);
        });

        sheet.querySelectorAll('[data-binding-action]').forEach(function (button) {
            button.addEventListener('click', function () {
                var scope = button.dataset.bindingScope;
                var action = button.dataset.bindingAction;
                var result = action === 'bind'
                    ? bindingController.bindCurrent(scope, target)
                    : bindingController.unbindCurrent(scope);
                if (!result || !result.ok) {
                    var reason = result && result.reason;
                    if (reason === 'no-character') toast('当前不是可绑定的单角色聊天', true);
                    else if (reason === 'no-chat') toast('当前聊天尚未完整加载，请稍后再试', true);
                    else toast('绑定操作失败，请重试', true);
                    return;
                }
                closeSheet(sheet);
                renderGrid();
                renderBottomStatus();
                if (typeof onChange === 'function') onChange();
                if (action === 'bind') {
                    toast(scope === 'chat' ? '已绑定到当前聊天' : '已绑定到当前角色卡');
                } else {
                    toast(scope === 'chat' ? '已解除当前聊天绑定' : '已解除当前角色绑定');
                }
            });
        });
    }

    function openBindingsOverviewSheet(itemRef, onChange) {
        if (!bindingController || !bindingsApi) {
            toast('绑定模块尚未就绪', true);
            return;
        }

        var item = getLogicalItem(itemRef, load());
        if (!item) {
            toast('找不到要查看的美化', true);
            return;
        }

        var sheet = createSheet([
            '<div class="tm-sheet-title"><i class="fa-solid fa-link"></i>绑定信息：' + esc(item.name) + '</div>',
            '<div class="tm-hint tm-bindings-all-hint">管理当前角色、当前聊天以及这个美化已有的全部绑定；聊天绑定优先于角色绑定。</div>',
            '<div id="tm-bindings-current-body"></div>',
            '<div class="tm-bindings-all-divider"><span>全部绑定</span></div>',
            '<div id="tm-bindings-all-body"></div>',
            '<div class="tm-edit-foot tm-bindings-all-foot"><button class="tm-btn tm-btn-danger" id="tm-bindings-clear-all">解除全部</button><button class="tm-btn tm-btn-outline" id="tm-bindings-all-close">关闭</button></div>',
        ].join(''));
        var currentBody = sheet.querySelector('#tm-bindings-current-body');
        var body = sheet.querySelector('#tm-bindings-all-body');
        var clearAllButton = sheet.querySelector('#tm-bindings-clear-all');

        function bindingLabel(record) {
            if (!record) return '';
            var recordTarget = bindingsApi.getTarget(record);
            if (!recordTarget) return '';
            if (recordTarget.kind === 'day-night') {
                var boundPair = pairsApi.getPair(load(), recordTarget.pairId);
                return boundPair ? boundPair.name : '已失效的日夜组合';
            }
            return recordTarget.themeName || '';
        }

        function currentBindingCard(scope, title, icon, available, label, record, target, resolution) {
            var boundTarget = record ? bindingsApi.getTarget(record) : null;
            var boundLabel = bindingLabel(record);
            var isThisTheme = bindingsApi.targetsEqual(boundTarget, target);
            var status = boundLabel ? ('已绑定：' + esc(boundLabel)) : '尚未绑定';
            var actionLabel = boundLabel
                ? (isThisTheme ? '已绑定此美化' : '改绑为此美化')
                : '绑定此美化';
            var priorityOn = resolution && resolution.scope === scope;
            return '<div class="tm-binding-card' + (priorityOn ? ' is-active' : '') + '">' +
                '<div class="tm-binding-head"><i class="fa-solid ' + icon + '"></i><div><strong>' + title + '</strong>' +
                '<small>' + (available ? esc(label) : (scope === 'chat' ? '当前没有可绑定的聊天窗口' : '群聊或主页不提供单角色绑定')) + '</small></div>' +
                (priorityOn ? '<span>当前生效</span>' : '') + '</div>' +
                '<div class="tm-binding-status">' + status + '</div>' +
                '<div class="tm-binding-actions">' +
                '<button class="tm-btn tm-btn-safe" data-current-binding-action="bind" data-binding-scope="' + scope + '"' +
                (!available || isThisTheme ? ' disabled' : '') + '>' + actionLabel + '</button>' +
                (boundLabel ? '<button class="tm-btn tm-btn-outline" data-current-binding-action="clear" data-binding-scope="' + scope + '">解除绑定</button>' : '') +
                '</div></div>';
        }

        function sectionHtml(scope, title, icon, references) {
            if (!references.length) return '';
            return '<section class="tm-bindings-all-section"><div class="tm-bindings-all-head"><span><i class="fa-solid ' + icon + '"></i>' + title + '</span><small>' + references.length + ' 项</small></div>' +
                '<div class="tm-bindings-all-list">' + references.map(function (reference) {
                    return '<div class="tm-bindings-all-row"><div class="tm-bindings-all-icon"><i class="fa-solid ' + icon + '"></i></div>' +
                        '<div class="tm-bindings-all-copy"><strong title="' + esc(reference.label) + '">' + esc(reference.label) + '</strong><small>' + (scope === 'character' ? '角色卡' : '聊天窗口') + '</small></div>' +
                        '<button type="button" class="tm-bindings-all-remove" data-binding-scope="' + scope + '" data-binding-key="' + esc(reference.key) + '">解除</button></div>';
                }).join('') + '</div></section>';
        }

        function refreshAfterRemoval(message) {
            bindingController.reconcile();
            renderGrid();
            renderBottomStatus();
            if (typeof onChange === 'function') onChange();
            render();
            toast(message);
        }

        function render() {
            var currentData = load();
            var currentItem = getLogicalItem(itemRef, currentData);
            if (!currentItem) {
                closeSheet(sheet);
                if (typeof onChange === 'function') onChange();
                return;
            }
            var target = getItemTarget(currentItem);
            var current = bindingController.getCurrentState();
            var info = current.context;
            currentBody.innerHTML = currentBindingCard(
                'character',
                '当前角色卡',
                'fa-user',
                !info.isGroup && !!info.characterKey,
                info.characterLabel || info.characterKey,
                current.character,
                target,
                current.resolution
            ) + currentBindingCard(
                'chat',
                '当前聊天窗口',
                'fa-message',
                !!(info.chatKey && info.chatId),
                info.chatLabel || info.chatId,
                current.chat,
                target,
                current.resolution
            );
            var refs = bindingsApi.listTargetReferences(currentData, target);
            var total = refs.characters.length + refs.chats.length;
            body.innerHTML = total
                ? sectionHtml('character', '角色卡', 'fa-user', refs.characters) + sectionHtml('chat', '聊天窗口', 'fa-message', refs.chats)
                : '<div class="tm-bindings-all-empty"><i class="fa-solid fa-link-slash"></i><strong>尚无绑定</strong><span>这个美化还没有绑定角色卡或聊天窗口</span></div>';
            clearAllButton.hidden = total < 2;

            body.querySelectorAll('.tm-bindings-all-remove').forEach(function (button) {
                button.addEventListener('click', function () {
                    var data = load();
                    var latestItem = getLogicalItem(itemRef, data);
                    var latestTarget = latestItem ? getItemTarget(latestItem) : null;
                    if (!latestTarget || !bindingsApi.targetsEqual(latestTarget, target)) {
                        render();
                        toast('这项绑定已经发生变化，请重新查看', true);
                        return;
                    }
                    var removed = bindingsApi.removeTargetReference(
                        data,
                        button.dataset.bindingScope,
                        button.dataset.bindingKey,
                        target
                    );
                    if (!removed) {
                        render();
                        toast('这项绑定已经发生变化，请重新查看', true);
                        return;
                    }
                    save(data);
                    refreshAfterRemoval('已解除这项绑定');
                });
            });
        }

        currentBody.addEventListener('click', function (event) {
            var button = event.target && event.target.closest
                ? event.target.closest('[data-current-binding-action]')
                : null;
            if (!button || !currentBody.contains(button)) return;
            var currentData = load();
            var currentItem = getLogicalItem(itemRef, currentData);
            if (!currentItem) { render(); return; }
            var target = getItemTarget(currentItem);
            var scope = button.dataset.bindingScope;
            var action = button.dataset.currentBindingAction;
            var result = action === 'bind'
                ? bindingController.bindCurrent(scope, target)
                : bindingController.unbindCurrent(scope);
            if (!result || !result.ok) {
                var reason = result && result.reason;
                if (reason === 'no-character') toast('当前不是可绑定的单角色聊天', true);
                else if (reason === 'no-chat') toast('当前聊天尚未完整加载，请稍后再试', true);
                else toast('绑定操作失败，请重试', true);
                return;
            }
            renderGrid();
            renderBottomStatus();
            if (typeof onChange === 'function') onChange();
            render();
            if (action === 'bind') toast(scope === 'chat' ? '已绑定到当前聊天' : '已绑定到当前角色卡');
            else toast(scope === 'chat' ? '已解除当前聊天绑定' : '已解除当前角色绑定');
        });

        clearAllButton.addEventListener('click', function () {
            var currentData = load();
            var currentItem = getLogicalItem(itemRef, currentData);
            if (!currentItem) {
                render();
                return;
            }
            var target = getItemTarget(currentItem);
            var refs = bindingsApi.listTargetReferences(currentData, target);
            var total = refs.characters.length + refs.chats.length;
            if (!total) {
                render();
                return;
            }
            if (!confirm('解除美化「' + currentItem.name + '」的全部 ' + total + ' 项角色 / 聊天绑定？')) return;
            var removed = bindingsApi.removeTargetReferences(currentData, target);
            if (!removed) {
                render();
                toast('绑定已经发生变化，请重新查看', true);
                return;
            }
            save(currentData);
            refreshAfterRemoval('已解除全部绑定');
        });

        sheet.querySelector('#tm-bindings-all-close').addEventListener('click', function () {
            closeSheet(sheet);
        });
        render();
    }

    // ── 编辑主题附加信息 ─────────────────────────────────────
    function openEditSheet(itemRef) {
        var d = load();
        var item = getLogicalItem(itemRef, d);
        if (!item || blockAmbiguousThemeItem(item)) return;
        var pair = item.kind === 'pair' ? pairsApi.getPair(d, item.pairId) : null;
        var meta = getItemMeta(d, item);
        var originalEditName = item.name;
        var originalEditCategory = meta.category || '';
        var editorItemRef = item.key;
        var currentOrdinaryThemeName = item.kind === 'theme' ? item.themeName : '';
        var selectedVariant = pair
            ? (pair.nightTheme === getCurrentThemeName() ? 'night' : (pair.dayTheme === getCurrentThemeName() ? 'day' : getPreferredPairVariant(pair.id)))
            : 'day';
        var variantDrafts = Object.create(null);
        if (pair) {
            ['day', 'night'].forEach(function (variant) {
                var name = variant === 'night' ? pair.nightTheme : pair.dayTheme;
                var variantMeta = peekMeta(d, name);
                variantDrafts[variant] = {
                    themeName: name,
                    imageData: variantMeta.imageData || null,
                    thumbData: variantMeta.thumbData || null,
                    crop: variantMeta.crop || null,
                    backgroundName: variantMeta.backgroundName || '',
                };
            });
        } else {
            var ordinaryMeta = peekMeta(d, item.themeName);
            variantDrafts.day = {
                themeName: item.themeName,
                imageData: ordinaryMeta.imageData || null,
                thumbData: ordinaryMeta.thumbData || null,
                crop: ordinaryMeta.crop || null,
                backgroundName: ordinaryMeta.backgroundName || '',
            };
        }
        var activeDraft = variantDrafts[selectedVariant] || variantDrafts.day;
        var themeName = activeDraft.themeName;
        var editImgData = activeDraft.imageData;
        var editThumbData = activeDraft.thumbData;
        var editCrop = activeDraft.crop;
        var editPreviewData = editImgData || editThumbData;
        var editCategory = meta.category || '';
        var editTags = (meta.tags || []).slice();
        var editBackgroundName = activeDraft.backgroundName;
        var itemTarget = getItemTarget(item);
        function buildBindingsOverviewHtml() {
            var refs = bindingsApi ? bindingsApi.listTargetReferences(load(), itemTarget) : { characters: [], chats: [] };
            var total = refs.characters.length + refs.chats.length;
            var summary = total
                ? (refs.characters.length ? refs.characters.length + ' 个角色' : '') +
                    (refs.characters.length && refs.chats.length ? ' · ' : '') +
                    (refs.chats.length ? refs.chats.length + ' 个聊天' : '')
                : '尚未绑定角色卡或聊天';
            return '<span class="tm-theme-bind-icon"><i class="fa-solid fa-link"></i></span>' +
                '<span class="tm-theme-bind-copy"><strong>角色 / 聊天绑定</strong><small>' + summary + '</small></span>' +
                '<i class="fa-solid fa-chevron-right tm-theme-bind-chevron"></i>';
        }
        function buildAvatarBindingOverviewHtml(userSet, characterSet) {
            var userCount = userSet && userSet.candidates ? userSet.candidates.length : 0;
            var characterCount = characterSet && characterSet.candidates ? characterSet.candidates.length : 0;
            var characterLabel = characterSet && characterSet.target && characterSet.target.label;
            var summary = 'User：' + (userCount ? '已绑定 ' + userCount + ' 张' : '当前美化未绑定') + ' · ' +
                (characterLabel ? characterLabel + '：' + (characterCount ? '已绑定 ' + characterCount + ' 张' : '当前美化未绑定') : '当前角色不可用');
            return '<span class="tm-theme-bind-icon"><i class="fa-solid fa-users"></i></span>' +
                '<span class="tm-theme-bind-copy"><strong>头像绑定</strong><small>' + esc(summary) + '</small></span>' +
                '<i class="fa-solid fa-chevron-right tm-theme-bind-chevron"></i>';
        }
        function buildAvatarBindingPoolHtml(bindingSet, items, kind) {
            var isCharacter = kind === 'character';
            if (!bindingSet || !items.length) {
                return '<div class="tm-user-avatar-bind-empty"><i class="fa-regular ' + (isCharacter ? 'fa-address-card' : 'fa-user') + '"></i><span><strong>当前美化未绑定' + (isCharacter ? '角色' : ' User') + '头像</strong><small>显示时继续按聊天、全局、原头像的顺序回退</small></span></div>';
            }
            return '<div class="tm-user-avatar-bind-pool">' + items.map(function (item) {
                var active = item.binding.active;
                return '<div class="tm-user-avatar-bind-item' + (active ? ' is-active' : '') + '">' +
                    '<button type="button" class="tm-user-avatar-bind-choice" data-theme-avatar-action="select" data-avatar-id="' + esc(item.binding.avatarId) + '">' +
                    '<span class="tm-user-avatar-bind-thumb"><img src="' + esc(imageLoaderApi.PLACEHOLDER_SRC) + '" data-image-key="' + esc(item.binding.avatarId) + '" alt=""></span>' +
                    '<span class="tm-user-avatar-bind-copy"><strong>' + esc(item.asset && item.asset.name || '头像资源') + '</strong><small>' + (active ? '当前使用' : '点按切换') + '</small></span>' +
                    (active ? '<i class="fa-solid fa-check"></i>' : '') + '</button>' +
                    '<button type="button" class="tm-user-avatar-bind-remove" data-theme-avatar-action="remove" data-avatar-id="' + esc(item.binding.avatarId) + '" aria-label="解除这个头像的绑定"><i class="fa-solid fa-link-slash"></i></button></div>';
            }).join('') + '</div>';
        }
        var bindingFieldsHtml =
            '<div class="tm-field"><label>绑定背景</label><button type="button" class="tm-bg-bind-card" id="tm-bg-bind">' + buildBackgroundBindHtml(editBackgroundName) + '</button></div>' +
            '<div class="tm-field"><label>角色 / 聊天绑定</label><button type="button" class="tm-theme-bind-card" id="tm-theme-bind-overview">' + buildBindingsOverviewHtml() + '</button></div>' +
            '<div class="tm-field"><label>头像绑定</label><button type="button" class="tm-theme-bind-card" id="tm-avatar-bind-overview"><span class="tm-theme-bind-icon"><i class="fa-solid fa-users"></i></span><span class="tm-theme-bind-copy"><strong>头像绑定</strong><small>正在读取头像绑定…</small></span><i class="fa-solid fa-chevron-right tm-theme-bind-chevron"></i></button></div>';
        var annotationFieldsHtml =
            '<div class="tm-field"><label>分类</label><button type="button" class="tm-picker-trigger" id="tm-edit-category-trigger"></button></div>' +
            '<div class="tm-field"><label>标签</label><button type="button" class="tm-picker-trigger" id="tm-edit-tags-trigger"></button></div>' +
            '<div class="tm-field"><label>作者</label><input type="text" id="tm-dauthor" placeholder="主题作者名" value="' + esc(meta.author || '') + '" /></div>' +
            '<div class="tm-field"><label>备注</label><textarea id="tm-ddesc" rows="2" placeholder="主题特点、适用场景等">' + esc(meta.description || '') + '</textarea></div>';
        var operationFieldsHtml =
            '<div class="tm-edit-operation-list">' +
            '<button type="button" class="tm-edit-operation" id="tm-edit-star"><span><i class="fa-solid fa-star"></i><strong>' + (meta.starred ? '取消收藏' : '收藏美化') + '</strong></span><i class="fa-solid fa-chevron-right"></i></button>' +
            (pair
                ? '<button type="button" class="tm-edit-operation tm-edit-operation-danger" id="tm-edit-manage-pair"><span><i class="fa-solid fa-circle-half-stroke"></i><strong>管理日夜组合</strong><small>解除组合或删除整组</small></span><i class="fa-solid fa-chevron-right"></i></button>'
                : '<button type="button" class="tm-edit-operation tm-edit-operation-danger" id="tm-edit-delete"><span><i class="fa-solid fa-trash"></i><strong>删除美化</strong></span><i class="fa-solid fa-chevron-right"></i></button>') +
            '</div>';

        var sheet = createSheet([
            '<div class="tm-sheet-title tm-edit-sheet-title"><span><i class="fa-solid fa-pen"></i>编辑美化</span>' +
            (pair ? '<div class="tm-day-night-toggle" role="group" aria-label="切换日夜版本">' +
                '<button type="button" data-variant="day" class="' + (selectedVariant === 'day' ? 'on' : '') + '" title="切换并固定为日间版"><i class="fa-solid fa-sun"></i></button>' +
                '<button type="button" data-variant="night" class="' + (selectedVariant === 'night' ? 'on' : '') + '" title="切换并固定为夜间版"><i class="fa-solid fa-moon"></i></button>' +
                '</div>' : '') + '</div>',
            '<div class="tm-field"><label>美化名称</label><input type="text" id="tm-edit-name" maxlength="80" value="' + esc(pair ? pair.name : item.name) + '" /></div>',
            buildDisclosureHtml('tm-edit-annotation-section', '标注信息', 'fa-note-sticky', annotationFieldsHtml),
            buildDisclosureHtml('tm-edit-binding-section', '绑定信息', 'fa-link', bindingFieldsHtml),
            buildDisclosureHtml('tm-edit-operation-section', '其他操作', 'fa-ellipsis', operationFieldsHtml),
            '<div class="tm-field"><label>预览截图</label>' +
            '<div class="tm-imgarea" id="tm-dimgarea">' + (editPreviewData ? '<img src="' + esc(editPreviewData) + '" />' : '<div class="tm-imgph"><i class="fa-regular fa-image"></i><span>点击或拖拽上传截图</span></div>') + '</div>' +
            '<input type="file" id="tm-dfile" accept="image/*" style="display:none" />' +
            '<div class="tm-img-actions"></div></div>',
            '<div class="tm-edit-foot"><button class="tm-btn tm-btn-outline" id="tm-dcopy-diagnostic" style="display:none">复制诊断</button><button class="tm-btn tm-btn-outline" id="tm-dcancel">取消</button><button class="tm-btn tm-btn-safe" id="tm-dsave">保存</button></div>',
        ].join(''));
        sheet.classList.add('tm-sheet-tall');

        function renderBackgroundBind() {
            sheet.querySelector('#tm-bg-bind').innerHTML = buildBackgroundBindHtml(editBackgroundName);
        }
        sheet.querySelector('#tm-bg-bind').addEventListener('click', function () {
            openBackgroundPickerSheet(editBackgroundName, function (name) {
                if (!editorSession || !editorSession.isActive() || editorSession.isSaving()) return;
                editBackgroundName = name || '';
                renderBackgroundBind();
            });
        });
        function renderBindingsOverview() {
            var button = sheet.querySelector('#tm-theme-bind-overview');
            if (button) button.innerHTML = buildBindingsOverviewHtml();
        }
        sheet.querySelector('#tm-theme-bind-overview').addEventListener('click', function () {
            openBindingsOverviewSheet(item.key, renderBindingsOverview);
        });
        var avatarBindingOverviewToken = 0;
        function renderAvatarBindingOverview() {
            var token = ++avatarBindingOverviewToken;
            var bindingThemeName = themeName;
            var button = sheet.querySelector('#tm-avatar-bind-overview');
            if (!button || !avatarRuntime || !avatarStore) return;
            button.innerHTML = '<span class="tm-theme-bind-icon"><i class="fa-solid fa-users"></i></span><span class="tm-theme-bind-copy"><strong>头像绑定</strong><small>正在读取头像绑定…</small></span><i class="fa-solid fa-chevron-right tm-theme-bind-chevron"></i>';
            Promise.all([
                avatarRuntime.getThemeAvatarBindingSet(bindingThemeName, 'user'),
                avatarRuntime.getThemeAvatarBindingSet(bindingThemeName, 'character'),
            ]).then(function (sets) {
                if (token !== avatarBindingOverviewToken || bindingThemeName !== themeName || !button.parentNode) return;
                button.innerHTML = buildAvatarBindingOverviewHtml(sets[0], sets[1]);
            }).catch(function (error) {
                if (token !== avatarBindingOverviewToken || !button.parentNode) return;
                var status = button.querySelector('.tm-theme-bind-copy small');
                if (status) status.textContent = '头像绑定读取失败';
                console.warn('[头像管理] 美化专属头像绑定读取失败:', error);
            });
        }

        function beginThemeAvatarEdit(bindingThemeName, kind, avatarId) {
            if (!bindingThemeName || !avatarId) return;
            if (closePopup() === false) return;
            function openEditor() {
                setTimeout(function () {
                    avatarRuntime.beginEdit({
                        kind: kind,
                        avatarId: avatarId,
                        bindingMode: 'theme',
                        themeName: bindingThemeName,
                    }).catch(function (error) { toast(error.message || '无法启动头像调整', true); });
                }, 32);
            }
            if (getCurrentThemeName() === bindingThemeName) { openEditor(); return; }
            applyManualTheme(bindingThemeName, function (ok, reason) {
                if (ok) openEditor();
                else if (reason !== 'superseded') toast('无法应用目标美化，头像调整未启动', true);
            });
        }
        function openAvatarBindingsSheet(bindingThemeName, onChange) {
            if (!bindingThemeName || !avatarRuntime || !avatarStore) {
                toast('头像绑定模块尚未就绪', true);
                return;
            }
            var capabilities = avatarRuntime.getCapabilities();
            var characterTarget = capabilities.character && capabilities.character.target;
            var selectedKind = 'user';
            var bindingSheet = createSheet([
                '<div class="tm-sheet-title"><i class="fa-solid fa-users"></i>头像绑定：' + esc(bindingThemeName) + '</div>',
                '<div class="tm-hint tm-bindings-all-hint">每个目标都可以为当前美化保存多个头像及各自的调整数据；新增头像请从头像库调整后保存到“当前美化”。</div>',
                '<div class="tm-avatar-bind-targets" role="group" aria-label="头像绑定目标"><button type="button" class="on" data-avatar-bind-kind="user" aria-pressed="true"><i class="fa-solid fa-user"></i> User</button><button type="button" data-avatar-bind-kind="character" aria-pressed="false"' + (characterTarget ? '' : ' disabled') + '><i class="fa-solid fa-address-card"></i> ' + esc(characterTarget && characterTarget.label || '当前角色不可用') + '</button></div>',
                '<div class="tm-user-avatar-bind-actions tm-user-avatar-bind-sheet-actions" id="tm-avatar-bind-actions"></div>',
                '<div class="tm-user-avatar-bind" id="tm-avatar-bind-sheet-body"><div class="tm-user-avatar-bind-loading">正在读取头像绑定…</div></div>',
                '<div class="tm-edit-foot tm-bindings-all-foot"><button class="tm-btn tm-btn-outline" id="tm-avatar-bind-close">关闭</button></div>',
            ].join(''));
            var body = bindingSheet.querySelector('#tm-avatar-bind-sheet-body');
            var actions = bindingSheet.querySelector('#tm-avatar-bind-actions');
            var currentBinding = null;
            var currentSet = null;
            var renderToken = 0;
            var loader = null;
            function disconnectLoader() {
                if (loader && typeof loader.disconnect === 'function') loader.disconnect();
                loader = null;
            }
            function changed() {
                if (typeof onChange === 'function') onChange();
            }
            function render() {
                var token = ++renderToken;
                var kind = selectedKind;
                disconnectLoader();
                actions.innerHTML = '';
                body.innerHTML = '<div class="tm-user-avatar-bind-loading">正在读取头像绑定…</div>';
                avatarRuntime.getThemeAvatarBindingSet(bindingThemeName, kind).then(function (bindingSet) {
                    return Promise.all(bindingSet.candidates.map(function (binding) {
                        return avatarStore.getAssetMetadata(binding.avatarId).then(function (asset) {
                            return { binding: binding, asset: asset };
                        });
                    })).then(function (items) { return { bindingSet: bindingSet, items: items }; });
                }).then(function (result) {
                    if (token !== renderToken || kind !== selectedKind || !body.parentNode) return;
                    currentSet = result.bindingSet;
                    currentBinding = currentSet.active;
                    actions.innerHTML = (currentBinding && currentSet.available ? '<button type="button" class="tm-btn tm-btn-outline" data-theme-avatar-action="adjust"><i class="fa-solid fa-sliders"></i> 调整当前头像</button>' : '') +
                        (currentSet.candidates.length ? '<button type="button" class="tm-btn tm-btn-danger" data-theme-avatar-action="clear">清除本组</button>' : '');
                    body.innerHTML = buildAvatarBindingPoolHtml(currentSet, result.items, kind);
                    loader = imageLoaderApi.createImageLoader({
                        root: body,
                        IntersectionObserver: null,
                        maxConcurrent: 4,
                        resolveSource: function (avatarId) { return avatarStore.getThumbnail(avatarId); },
                    });
                    loader.observe(body.querySelectorAll('.tm-user-avatar-bind-thumb img'));
                }).catch(function (error) {
                    if (token !== renderToken || kind !== selectedKind || !body.parentNode) return;
                    actions.innerHTML = '';
                    body.innerHTML = '<div class="tm-user-avatar-bind-loading">头像绑定读取失败</div>';
                    console.warn('[头像管理] 美化专属头像绑定读取失败:', error);
                });
            }
            bindingSheet.addEventListener('click', function (event) {
                var kindButton = event.target && event.target.closest ? event.target.closest('[data-avatar-bind-kind]') : null;
                if (kindButton && bindingSheet.contains(kindButton) && !kindButton.disabled) {
                    selectedKind = kindButton.getAttribute('data-avatar-bind-kind') === 'character' ? 'character' : 'user';
                    bindingSheet.querySelectorAll('[data-avatar-bind-kind]').forEach(function (button) {
                        var active = button.getAttribute('data-avatar-bind-kind') === selectedKind;
                        button.classList.toggle('on', active);
                        button.setAttribute('aria-pressed', active ? 'true' : 'false');
                    });
                    render();
                    return;
                }
                var button = event.target && event.target.closest ? event.target.closest('[data-theme-avatar-action]') : null;
                if (!button || !bindingSheet.contains(button)) return;
                var action = button.getAttribute('data-theme-avatar-action');
                var avatarId = button.getAttribute('data-avatar-id');
                var label = selectedKind === 'character' ? '当前角色' : 'User';
                if (action === 'select' && avatarId) {
                    avatarRuntime.setThemeAvatarBinding(bindingThemeName, selectedKind, avatarId).then(function () {
                        changed(); render(); toast('已切换当前美化的' + label + '头像');
                    }).catch(function (error) { toast(error.message || '切换头像失败', true); });
                } else if (action === 'remove' && avatarId) {
                    avatarRuntime.removeThemeAvatarBinding(bindingThemeName, selectedKind, avatarId).then(function () {
                        changed(); render(); toast('已解除这个头像与当前美化的绑定');
                    }).catch(function (error) { toast(error.message || '解除头像绑定失败', true); });
                } else if (action === 'adjust' && currentBinding && currentSet && currentSet.available) {
                    disconnectLoader();
                    beginThemeAvatarEdit(bindingThemeName, selectedKind, currentBinding.avatarId);
                } else if (action === 'clear') {
                    avatarRuntime.clearThemeAvatarBinding(bindingThemeName, selectedKind).then(function () {
                        currentBinding = null;
                        changed(); render(); toast('已清除当前美化的全部' + label + '头像绑定');
                    }).catch(function (error) { toast(error.message || '解除头像绑定失败', true); });
                }
            });
            bindingSheet.querySelector('#tm-avatar-bind-close').addEventListener('click', function () {
                disconnectLoader();
                closeSheet(bindingSheet);
            });
            if (uiSheetsApi && typeof uiSheetsApi.setBeforeClose === 'function') {
                uiSheetsApi.setBeforeClose(bindingSheet, function () { disconnectLoader(); return true; });
            }
            render();
        }
        sheet.querySelector('#tm-avatar-bind-overview').addEventListener('click', function () {
            openAvatarBindingsSheet(themeName, renderAvatarBindingOverview);
        });
        renderAvatarBindingOverview();

        function pickerTriggerHtml(icon, title, summary) {
            return '<span class="tm-picker-trigger-icon"><i class="fa-solid ' + icon + '"></i></span>' +
                '<span class="tm-picker-trigger-copy"><strong>' + esc(title) + '</strong><small>' + esc(summary) + '</small></span>' +
                '<i class="fa-solid fa-chevron-right tm-picker-trigger-chevron"></i>';
        }
        function renderCategoryTrigger() {
            sheet.querySelector('#tm-edit-category-trigger').innerHTML = pickerTriggerHtml('fa-folder', '选择分类', editCategory || '无分类');
        }
        function renderTagsTrigger() {
            var summary = editTags.length ? editTags.join(' · ') : '尚未设置标签';
            sheet.querySelector('#tm-edit-tags-trigger').innerHTML = pickerTriggerHtml('fa-tags', '管理标签', summary);
        }
        renderCategoryTrigger();
        renderTagsTrigger();
        sheet.querySelector('#tm-edit-category-trigger').addEventListener('click', function () {
            openCategoryPicker({
                title: '选择分类',
                hint: '为当前美化设置分类',
                selected: editCategory,
                allowClear: true,
                onSelect: function (category) {
                    if (!editorSession || !editorSession.isActive() || editorSession.isSaving()) return;
                    editCategory = category || '';
                    renderCategoryTrigger();
                },
            });
        });
        sheet.querySelector('#tm-edit-tags-trigger').addEventListener('click', function () {
            openTagPicker({
                title: '管理标签',
                hint: '选择已有标签，或输入新标签后应用',
                selectedTags: editTags,
                allowClear: true,
                onApply: function (tags) {
                    if (!editorSession || !editorSession.isActive() || editorSession.isSaving()) return;
                    editTags = tags.slice();
                    renderTagsTrigger();
                },
            });
        });

        // 图片
        var fileInp = sheet.querySelector('#tm-dfile');
        var imgArea = sheet.querySelector('#tm-dimgarea');
        var imgActions = sheet.querySelector('.tm-img-actions');
        function renderImageActions() {
            var hasImage = Boolean(editImgData || editThumbData);
            imgActions.innerHTML = '<button class="tm-btn tm-btn-outline" id="tm-dpick" style="font-size:.8em"><i class="fa-solid fa-image"></i> 选择图片</button>' +
                (hasImage ? '<button class="tm-btn tm-btn-outline" id="tm-dview" style="font-size:.8em"><i class="fa-solid fa-expand"></i> 查看大图</button>' +
                    '<button class="tm-btn tm-btn-outline" id="tm-dadjust" style="font-size:.8em"><i class="fa-solid fa-up-down-left-right"></i> 调整显示区域</button>' +
                    '<button class="tm-btn tm-btn-danger" id="tm-dclr" style="font-size:.8em">删除图片</button>' : '');
        }
        function setImg(data, thumb, crop) {
            editImgData = data || null;
            editThumbData = thumb || null;
            editCrop = crop || null;
            var preview = editImgData || editThumbData;
            imgArea.innerHTML = preview ? '<img src="' + esc(preview) + '" />' : '<div class="tm-imgph"><i class="fa-regular fa-image"></i><span>点击或拖拽上传截图</span></div>';
            renderImageActions();
        }
        function captureVariantDraft() {
            var draft = variantDrafts[selectedVariant];
            if (!draft) return;
            draft.imageData = editImgData;
            draft.thumbData = editThumbData;
            draft.crop = editCrop;
            draft.backgroundName = editBackgroundName;
        }
        function captureEditSnapshot() {
            captureVariantDraft();
            return {
                name: sheet.querySelector('#tm-edit-name').value.trim(),
                category: editCategory,
                author: sheet.querySelector('#tm-dauthor').value.trim(),
                description: sheet.querySelector('#tm-ddesc').value.trim(),
                tags: editTags.slice(),
                variants: cloneJson(variantDrafts),
            };
        }
        function loadVariantDraft(variant) {
            var draft = variantDrafts[variant];
            if (!draft) return;
            selectedVariant = variant;
            themeName = draft.themeName;
            editBackgroundName = draft.backgroundName || '';
            editImgData = draft.imageData || null;
            editThumbData = draft.thumbData || null;
            editCrop = draft.crop || null;
            renderBackgroundBind();
            setImg(editImgData, editThumbData, editCrop);
            renderAvatarBindingOverview();
            sheet.querySelectorAll('.tm-day-night-toggle button').forEach(function (button) {
                button.classList.toggle('on', button.dataset.variant === variant);
            });
        }
        if (pair) {
            sheet.querySelectorAll('.tm-day-night-toggle button').forEach(function (button) {
                button.addEventListener('click', function () {
                    var variant = button.dataset.variant === 'night' ? 'night' : 'day';
                    var preference = pairsApi.normalizeDayNightPreference(load().dayNightPreference);
                    if (variant !== selectedVariant) {
                        captureVariantDraft();
                        loadVariantDraft(variant);
                    }
                    if (preference.mode === 'manual' && preference.manualVariant === variant) return;
                    persistManualDayNightVariant(variant, 'editor-manual-switch', true);
                    applyManualTheme(themeName, function (ok, reason) {
                        if (ok) {
                            renderGrid();
                            renderBottomStatus();
                            updateBtn();
                        } else if (reason !== 'superseded') {
                            toast('无法应用' + (variant === 'night' ? '夜间版' : '日间版') + '，当前美化已保留', true);
                        }
                    });
                });
            });
        }
        function handleFile(f) {
            if (!f || !imageToolsApi.inferImageMime(f)) return;
            imageToolsApi.readImageFile(f).then(function (dataUrl) {
                if (!editorSession || !editorSession.isActive() || editorSession.isSaving()) return;
                compressImage(dataUrl, function (c) {
                    if (!editorSession || !editorSession.isActive() || editorSession.isSaving()) return;
                    openImageCropSheet(c, null, function (res) {
                        if (!editorSession || !editorSession.isActive() || editorSession.isSaving()) return;
                        setImg(res.imageData, res.thumbData, res.crop);
                    });
                });
            }).catch(function (error) {
                console.error('[Theme Manager] preview image read failed', error);
                toast(error.message || '图片读取失败', true);
            });
        }
        function adjustCurrentImage() {
            var source = editImgData || editThumbData;
            if (!source) return;
            openImageCropSheet(source, editCrop, function (res) {
                if (!editorSession || !editorSession.isActive() || editorSession.isSaving()) return;
                setImg(res.imageData, res.thumbData, res.crop);
            });
        }
        renderImageActions();
        imgActions.addEventListener('click', function (e) {
            var button = e.target && e.target.closest ? e.target.closest('button') : null;
            if (!button || !imgActions.contains(button)) return;
            if (button.id === 'tm-dpick') fileInp.click();
            else if (button.id === 'tm-dview') {
                var source = editImgData || editThumbData;
                if (source) uiSheetsApi.openImageLightbox([{ key: 'draft', label: sheet.querySelector('#tm-edit-name').value.trim() || originalEditName, source: source }], 'draft');
            }
            else if (button.id === 'tm-dadjust') adjustCurrentImage();
            else if (button.id === 'tm-dclr') setImg(null, null, null);
        });
        imgArea.addEventListener('click', function () { fileInp.click(); });
        fileInp.addEventListener('change', function () {
            var files = imageToolsApi.snapshotInputFiles(fileInp);
            if (files[0]) handleFile(files[0]);
            fileInp.value = '';
        });
        imgArea.addEventListener('dragover', function (e) { e.preventDefault(); imgArea.classList.add('drag'); });
        imgArea.addEventListener('dragleave', function () { imgArea.classList.remove('drag'); });
        imgArea.addEventListener('drop', function (e) { e.preventDefault(); imgArea.classList.remove('drag'); if (e.dataTransfer && e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]); });

        var editorSession = editorDraftApi.createSession(captureEditSnapshot());
        var persistFailureUi = modules.persistFailureUi || ns.persistFailureUi;
        var diagnosticButton = sheet.querySelector('#tm-dcopy-diagnostic');
        var lastSaveDiagnosticText = '';
        var diagnosticRequestId = 0;

        function refreshStarOperation() {
            var button = sheet.querySelector('#tm-edit-star');
            if (!button) return;
            var currentItem = getLogicalItem(editorItemRef, load());
            var currentMeta = currentItem ? getItemMeta(load(), currentItem) : null;
            var label = button.querySelector('strong');
            if (label) label.textContent = currentMeta && currentMeta.starred ? '取消收藏' : '收藏美化';
        }
        sheet.querySelector('#tm-edit-star').addEventListener('click', function () {
            var dd = load();
            var currentItem = getLogicalItem(editorItemRef, dd);
            var currentMeta = currentItem ? getItemMetaForWrite(dd, currentItem) : null;
            if (!currentMeta) { toast('美化已发生变化，请关闭后重试', true); return; }
            currentMeta.starred = !currentMeta.starred;
            save(dd);
            refreshStarOperation();
            refreshSingleItemCard(currentItem.key, { starred: true });
            toast(currentMeta.starred ? '⭐ 已收藏' : '已取消收藏');
        });
        var managePairButton = sheet.querySelector('#tm-edit-manage-pair');
        if (managePairButton) managePairButton.addEventListener('click', function () {
            if (!closeSheet(sheet)) return;
            openDayNightDeleteSheet(pair.id);
        });
        var deleteButton = sheet.querySelector('#tm-edit-delete');
        if (deleteButton) deleteButton.addEventListener('click', function () {
            var deletingName = currentOrdinaryThemeName;
            if (!deletingName) return;
            if (!confirm('删除美化「' + deletingName + '」？\n这会从 SillyTavern 主题列表中真实删除，不只是从插件移除。')) return;
            editorSession.invalidate();
            closeSheet(sheet, { force: true });
            deleteThemeEverywhere(deletingName, function (ok, reason) {
                if (ok) toast('已删除美化');
                else toast('删除失败：' + (reason || '请查看控制台'), true);
            });
        });

        diagnosticButton.addEventListener('click', function () {
            copyTextToClipboard(lastSaveDiagnosticText).then(function (copied) {
                toast(copied ? '诊断信息已复制' : '无法复制诊断信息，请查看控制台', !copied);
            });
        });

        function setEditorSaving(saving) {
            sheet.querySelectorAll('input,select,textarea,button').forEach(function (control) {
                if (control.id !== 'tm-dcancel') control.disabled = saving;
            });
            var button = sheet.querySelector('#tm-dsave');
            if (button) button.textContent = saving ? '保存中...' : '保存';
        }

        function handlePersistFailure(token, error) {
            if (!editorSession.failSave(token)) return;
            setEditorSaving(false);
            var normalized = storageApi && typeof storageApi.normalizePersistError === 'function'
                ? storageApi.normalizePersistError(error)
                : error;
            console.warn('[美化管理] metadata 保存失败，草稿已保留:', normalized || error);
            toast(persistFailureUi.formatMessage(normalized), true);
            lastSaveDiagnosticText = '';
            diagnosticButton.style.display = 'none';
            var requestId = ++diagnosticRequestId;
            if (!storageApi || typeof storageApi.collectDiagnostics !== 'function') return;
            storageApi.collectDiagnostics(normalized).then(function (diagnostic) {
                if (requestId !== diagnosticRequestId || !editorSession.isActive() || !diagnosticButton.parentNode) return;
                lastSaveDiagnosticText = persistFailureUi.formatDiagnostic(diagnostic);
                diagnosticButton.style.display = '';
            });
        }
        uiSheetsApi.setBeforeClose(sheet, function () {
            var dirty = editorSession.isDirty(captureEditSnapshot());
            if (!dirty && !editorSession.isSaving()) {
                editorSession.invalidate();
                return true;
            }
            if (editorSession.isSaving()) {
                toast('美化仍在保存处理中，请等待完成后再关闭', true);
                return false;
            }
            var message = '当前修改尚未保存，是否放弃修改？';
            if (!confirm(message)) return false;
            editorSession.invalidate();
            return true;
        });
        sheet.querySelector('#tm-dcancel').addEventListener('click', function () { closeSheet(sheet); });
        sheet.querySelector('#tm-dsave').addEventListener('click', function () {
            var snapshot = captureEditSnapshot();
            var requestedName = snapshot.name;
            if (!requestedName) { toast('美化名称不能为空', true); return; }
            if (pair) {
                var duplicate = getLogicalItems(load()).some(function (other) {
                    return other.key !== item.key && other.name === requestedName;
                });
                if (duplicate) { toast('已有同名美化，请换一个名称', true); return; }
            }
            var saveTicket = editorSession.beginSave(snapshot);
            if (!saveTicket) return;
            diagnosticRequestId += 1;
            lastSaveDiagnosticText = '';
            diagnosticButton.style.display = 'none';
            setEditorSaving(true);

            function uploadDraft(draft, callback) {
                uploadImage(draft.imageData, function (imgErr, imgUrl) {
                    if (imgErr) { callback(imgErr); return; }
                    uploadImage(draft.thumbData, function (thumbErr, thumbUrl) {
                        if (thumbErr) { callback(thumbErr); return; }
                        callback(null, {
                            themeName: draft.themeName,
                            imageData: imgUrl || draft.imageData || null,
                            thumbData: draft.thumbData ? (thumbUrl || draft.thumbData) : null,
                            crop: draft.crop || null,
                            backgroundName: draft.backgroundName || '',
                        });
                    });
                });
            }

            var draftKeys = pair ? ['day', 'night'] : ['day'];
            var uploaded = Object.create(null);
            var remaining = draftKeys.length;
            var uploadFailed = false;
            draftKeys.forEach(function (variant) {
                uploadDraft(saveTicket.snapshot.variants[variant], function (err, result) {
                    if (!editorSession.isCurrent(saveTicket.token) || uploadFailed) return;
                    if (err) {
                        uploadFailed = true;
                        editorSession.failSave(saveTicket.token);
                        setEditorSaving(false);
                        toast('图片处理失败，草稿仍保留，请重试', true);
                        return;
                    }
                    uploaded[variant] = result;
                    remaining -= 1;
                    if (remaining === 0) prepareSaveTarget();
                });
            });

            function failRename(reason) {
                editorSession.failSave(saveTicket.token);
                setEditorSaving(false);
                if (reason === 'duplicate') toast('已有同名美化', true);
                else if (reason === 'filename-conflict') toast('名称经酒馆文件名清理后与已有主题冲突', true);
                else if (reason === 'invalid-filename') toast('该名称无法生成有效的主题文件名', true);
                else if (reason === 'manager-identity-conflict') toast('目标名称存在遗留美化管理数据，未执行改名', true);
                else if (reason === 'incomplete') toast('主题尚未完整加载，不能安全改名', true);
                else if (reason === 'verify-failed') toast('新主题最终验证失败，改名已回滚并保留旧主题', true);
                else if (reason === 'delete-failed') toast('旧主题删除或最终验证失败，改名已回滚', true);
                else if (reason === 'rollback-failed') toast('改名失败且自动回滚未完成，请立即检查主题文件', true);
                else if (reason === 'inventory-failed') toast('无法刷新主题列表，未执行改名', true);
                else toast('重命名失败，旧主题已保留', true);
            }

            function prepareSaveTarget() {
                if (!editorSession.isCurrent(saveTicket.token)) return;
                if (pair || requestedName === currentOrdinaryThemeName) {
                    finishSave();
                    return;
                }
                renameThemeEverywhere(currentOrdinaryThemeName, requestedName, function (ok, reason) {
                    if (!editorSession.isCurrent(saveTicket.token)) return;
                    if (!ok) { failRename(reason); return; }
                    currentOrdinaryThemeName = requestedName;
                    editorItemRef = 'theme:' + requestedName;
                    variantDrafts.day.themeName = requestedName;
                    if (uploaded.day) uploaded.day.themeName = requestedName;
                    var renamedItem = getLogicalItem(editorItemRef, load());
                    if (renamedItem) itemTarget = getItemTarget(renamedItem);
                    finishSave();
                });
            }

            function finishSave() {
                if (!editorSession.isCurrent(saveTicket.token)) return;
                var dd = cloneJson(load());
                var refreshedItem = getLogicalItem(editorItemRef, dd);
                if (!refreshedItem) {
                    editorSession.failSave(saveTicket.token);
                    setEditorSaving(false);
                    toast('美化已发生变化，请关闭后重试', true);
                    return;
                }
                var shared = getItemMetaForWrite(dd, refreshedItem);
                shared.category = saveTicket.snapshot.category;
                shared.author = saveTicket.snapshot.author;
                shared.description = saveTicket.snapshot.description;
                shared.tags = saveTicket.snapshot.tags.slice();
                if (refreshedItem.kind === 'pair') {
                    pairsApi.renamePair(dd, refreshedItem.pairId, requestedName);
                    ['day', 'night'].forEach(function (variant) {
                        var result = uploaded[variant];
                        var variantMeta = ensureMeta(dd, result.themeName);
                        variantMeta.backgroundName = result.backgroundName;
                        variantMeta.imageData = result.imageData;
                        variantMeta.thumbData = result.thumbData;
                        variantMeta.crop = result.crop;
                    });
                } else {
                    var ordinary = uploaded.day;
                    shared.backgroundName = ordinary.backgroundName;
                    shared.imageData = ordinary.imageData;
                    shared.thumbData = ordinary.thumbData;
                    shared.crop = ordinary.crop;
                }
                var persist;
                try {
                    if (shared.category === originalEditCategory) applyAutomaticCategories(dd);
                    persist = save(dd);
                } catch (err) {
                    handlePersistFailure(saveTicket.token, err);
                    return;
                }
                Promise.resolve(persist).then(function () {
                    if (!editorSession.completeSave(saveTicket.token, saveTicket.snapshot)) return;
                    closeSheet(sheet, { force: true });
                    var editEffects = {
                        name: requestedName !== originalEditName,
                        category: shared.category !== originalEditCategory,
                        searchable: true,
                        layout: refreshedItem.kind === 'pair' && requestedName !== originalEditName,
                    };
                    var currentTheme = getCurrentThemeName();
                    if (refreshedItem.themeNames.indexOf(currentTheme) !== -1) {
                        applyBoundBackground(currentTheme, function () {
                            toast('✨ 已保存');
                            renderCatbar(); refreshSingleItemCard(refreshedItem.key, editEffects); renderBottomStatus();
                        });
                    } else {
                        toast('✨ 已保存');
                        renderCatbar(); refreshSingleItemCard(refreshedItem.key, editEffects);
                    }
                }).catch(function (err) {
                    handlePersistFailure(saveTicket.token, err);
                });
            }
        });
    }

    function mergeImportedAnnotations(imported) {
        var dd = load();
        metadataApi.ensureThemeMetaDictionary(dd);
        var importedCount = 0;
        var importedBindingCount = 0;
        var importedPairCount = 0;
        var importedSeriesCount = 0;
        var skippedImportedSeriesCount = 0;
        var importedPairIdMap = Object.create(null);
        var skippedImportedPairIds = Object.create(null);
        var relationshipDiagnostics = [];

        if (imported.categories) imported.categories.forEach(function (c) { if (dd.categories.indexOf(c) === -1) dd.categories.push(c); });
        Object.keys(imported.themeMeta || {}).forEach(function (k) {
            var imp = imported.themeMeta[k] || {};
            if (!Object.prototype.hasOwnProperty.call(dd.themeMeta, k)) {
                dd.themeMeta[k] = imp;
                if (!Array.isArray(dd.themeMeta[k].tags)) dd.themeMeta[k].tags = [];
                if (dd.themeMeta[k].thumbData === undefined) dd.themeMeta[k].thumbData = null;
                if (dd.themeMeta[k].crop === undefined) dd.themeMeta[k].crop = null;
            } else {
                var existing = ensureMeta(dd, k);
                if (!Array.isArray(existing.tags)) existing.tags = [];
                imageToolsApi.mergeMissingPreview(existing, imp);
                if (!existing.category && imp.category) existing.category = imp.category;
                if (!existing.backgroundName && imp.backgroundName) existing.backgroundName = imp.backgroundName;
                if (imp.tags) imp.tags.forEach(function (t) { if (existing.tags.indexOf(t) === -1) existing.tags.push(t); });
                if (!existing.author && imp.author) existing.author = imp.author;
                if (!existing.description && imp.description) existing.description = imp.description;
            }
            importedCount++;
        });
        if (pairsApi && imported.dayNight) {
            var rawPairs = imported.dayNight.pairs || imported.dayNight;
            var pairOutcome = pairsApi.importPairs(dd, rawPairs, stThemeList);
            importedPairCount = pairOutcome.imported;
            importedPairIdMap = pairOutcome.idMap || {};
            (pairOutcome.skippedIds || []).forEach(function (id) { skippedImportedPairIds[id] = true; });
            relationshipDiagnostics = relationshipDiagnostics.concat(pairOutcome.diagnostics || []);
        }
        if (seriesApi && imported.series && typeof imported.series === 'object') {
            var importedGroups = imported.series.groups || imported.series;
            var seriesOutcome = seriesApi.importSeries(dd, importedGroups, {
                availableThemeNames: stThemeList,
                availablePairIds: Object.keys(pairsApi.ensureState(dd).pairs),
                pairIdMap: importedPairIdMap,
                skippedPairIds: Object.keys(skippedImportedPairIds),
                requirePairIdMap: true,
            });
            importedSeriesCount = seriesOutcome.imported;
            skippedImportedSeriesCount = seriesOutcome.skipped;
            relationshipDiagnostics = relationshipDiagnostics.concat(seriesOutcome.diagnostics || []);
        }
        if (bindingsApi && imported.bindings && typeof imported.bindings === 'object') {
            var importedBindingData = { bindings: cloneJson(imported.bindings) };
            var sourceBindings = bindingsApi.ensureState(importedBindingData);
            var targetBindings = bindingsApi.ensureMutableState(dd);
            ['characters', 'chats'].forEach(function (scope) {
                Object.keys(sourceBindings[scope]).forEach(function (key) {
                    var record = sourceBindings[scope][key];
                    var target = bindingsApi.getTarget(record);
                    if (target && target.kind === 'day-night') {
                        if (importedPairIdMap[target.pairId]) target.pairId = importedPairIdMap[target.pairId];
                        else if (skippedImportedPairIds[target.pairId]) return;
                        if (!pairsApi.getPair(dd, target.pairId)) return;
                    }
                    targetBindings[scope][key] = record;
                    importedBindingCount += 1;
                });
            });
            if (!targetBindings.manualTarget && sourceBindings.manualTarget) {
                var manualTarget = bindingsApi.normalizeTarget(sourceBindings.manualTarget);
                if (manualTarget && manualTarget.kind === 'day-night') {
                    if (importedPairIdMap[manualTarget.pairId]) manualTarget.pairId = importedPairIdMap[manualTarget.pairId];
                    else if (skippedImportedPairIds[manualTarget.pairId]) manualTarget = null;
                    if (manualTarget && !pairsApi.getPair(dd, manualTarget.pairId)) manualTarget = null;
                }
                if (manualTarget) {
                    targetBindings.manualTarget = manualTarget;
                    targetBindings.manualTheme = manualTarget.kind === 'theme' ? manualTarget.themeName : '';
                }
            }
        }

        if (relationshipDiagnostics.length > 0) console.warn('[美化管理] 标注备份关系诊断:', relationshipDiagnostics);
        save(dd);
        if (bindingController && importedBindingCount) bindingController.reconcile();
        renderCatbar();
        renderGrid();
        renderBottomStatus();
        toast('✅ 导入成功：' + importedCount + ' 个美化标注' +
            (importedPairCount ? '，' + importedPairCount + ' 组日夜美化' : '') +
            (importedSeriesCount ? '，' + importedSeriesCount + ' 个系列' : '') +
            (skippedImportedSeriesCount ? '；' + skippedImportedSeriesCount + ' 个系列未新增（可能已存在、成员缺失或归属冲突）' : '') +
            (relationshipDiagnostics.filter(function (item) { return item.severity !== 'info'; }).length ? '；关系诊断见控制台' : '') +
            (importedBindingCount ? '，' + importedBindingCount + ' 个绑定' : ''));
    }

    function openCategoryExportSheet() {
        var d = load();
        var rows = '';
        function countForCat(cat) {
            return getItemsForDisplayCategory(d, cat).length;
        }
        rows += '<button class="tm-cat-export-item" data-cat="__uncategorized__"><span>未分类</span><small>' + countForCat('__uncategorized__') + ' 个美化</small></button>';
        d.categories.forEach(function (cat) {
            rows += '<button class="tm-cat-export-item" data-cat="' + esc(cat) + '"><span>' + esc(cat) + '</span><small>' + countForCat(cat) + ' 个美化</small></button>';
        });
        if (d.categories.length === 0) rows += '<div class="tm-hint">还没有自定义分类，可以先导出未分类美化。</div>';

        var sheet = createSheet([
            '<div class="tm-sheet-title"><i class="fa-solid fa-folder-open"></i>导出分类</div>',
            '<div class="tm-import-cat-list">' + rows + '</div>',
            '<div class="tm-edit-foot"><button class="tm-btn tm-btn-outline" id="tm-cat-exp-cancel">取消</button></div>',
        ].join(''));

        sheet.querySelector('#tm-cat-exp-cancel').addEventListener('click', function () { closeSheet(sheet); });
        sheet.querySelectorAll('.tm-cat-export-item').forEach(function (btn) {
            btn.addEventListener('click', function () {
                var cat = btn.dataset.cat || '';
                var count = countForCat(cat);
                if (count <= 0) { toast('这个分类里没有美化', true); return; }
                closeSheet(sheet);
                var data = load();
                var targetItems = getItemsForDisplayCategory(data, cat);
                var targetNames = expandItemThemeNames(targetItems);
                themeTransfer.prepareExport(targetNames, { themeMeta: data.themeMeta })
                    .then(function (prepared) {
                        reportExportWarnings(prepared);
                        var catName = cat === '__uncategorized__' ? '未分类' : cat;
                        var exportedPairs = pairsApi.exportPairs(data, prepared.themes.map(function (theme) { return theme.name; }));
                        var seriesManifest = buildSeriesManifestForBundle(data, prepared.themes, exportedPairs);
                        var skippedSeriesCount = Math.max(0, countSeriesForItems(data, targetItems) - seriesManifest.groups.length);
                        var bundle = {
                            type: 'theme-mgr-theme-bundle',
                            version: 1,
                            exportedAt: new Date().toISOString(),
                            exportScope: { type: 'category', category: catName },
                            themes: prepared.themes,
                            categories: cat === '__uncategorized__' ? [] : [cat],
                            themeMeta: buildThemeMetaForBundle(prepared.themes),
                            dayNightPairs: exportedPairs,
                            seriesManifest: seriesManifest,
                            themeFingerprints: prepared.fingerprints.byFingerprint,
                            themeCompatibilityReport: prepared.report,
                        };
                        var safeName = String(catName).replace(/[\\/:*?"<>|]/g, '_').slice(0, 40) || 'category';
                        var reportText = prepared.report.legacyCount > 0
                            ? '，兼容补齐 ' + prepared.report.legacyCount + ' 个旧主题的 ' + prepared.report.filledFieldCount + ' 个字段'
                            : '';
                        downloadJsonFile('theme-mgr-' + safeName + '-' + new Date().toISOString().slice(0, 10) + '.json', bundle, function (assetCount) {
                            toast('✅ 已安全导出「' + catName + '」：' + prepared.themes.length + ' 个' + reportText +
                                (assetCount ? '，含 ' + assetCount + ' 张图片' : '') +
                                (skippedSeriesCount ? '；' + skippedSeriesCount + ' 个系列因成员不完整未附带关系' : ''));
                        });
                    })
                    .catch(function (err) {
                        console.warn('[美化管理] 导出分类安全检查失败:', err);
                        toast('导出分类已中止：' + err.message, true);
                    });
            });
        });
    }

    // ── 设置 ─────────────────────────────────────────────────
    function avatarImageGcError(message, code) {
        var error = new Error(message);
        error.code = code || 'AVATAR_IMAGE_GC_FAILED';
        return error;
    }

    function readAvatarImageGcJson(response, fallbackMessage) {
        if (!response || typeof response.json !== 'function') return Promise.reject(avatarImageGcError(fallbackMessage, 'AVATAR_IMAGE_GC_INVALID'));
        return response.json().catch(function () {
            throw avatarImageGcError(fallbackMessage, 'AVATAR_IMAGE_GC_INVALID');
        }).then(function (body) {
            if (!body || typeof body !== 'object' || Array.isArray(body)) throw avatarImageGcError(fallbackMessage, 'AVATAR_IMAGE_GC_INVALID');
            if (!response.ok || body.ok !== true) {
                var code = typeof body.error === 'string' ? body.error : 'AVATAR_IMAGE_GC_FAILED';
                var message = code === 'IMAGE_GC_CHANGED'
                    ? '孤儿图片状态已变化，请重新扫描确认'
                    : (code === 'AVATAR_GC_BLOCKED' ? '头像数据未通过完整校验，已中止清理' : fallbackMessage);
                throw avatarImageGcError(message, code);
            }
            return body;
        });
    }

    function requestAvatarImageGc(dryRun, expectedFiles) {
        return global.fetch(SERVER_BASE + '/status', { method: 'GET', credentials: 'same-origin', cache: 'no-cache' })
            .then(function (response) { return readAvatarImageGcJson(response, '无法确认后端清理能力'); })
            .then(function (status) {
                var capability = status.capabilities && status.capabilities.imageGarbageCollection;
                if (!capability || capability.version !== 1 || capability.avatarAware !== true || capability.dryRun !== true || capability.exactCommit !== true) {
                    throw avatarImageGcError('当前后端版本不支持安全清理孤儿图片，请先更新 theme-mgr-server', 'AVATAR_IMAGE_GC_UNSUPPORTED');
                }
                return getPostHeaders().then(function (headers) {
                    var payload = { dryRun: dryRun === true };
                    if (!dryRun) payload.expectedFiles = Array.isArray(expectedFiles) ? expectedFiles.slice() : [];
                    return global.fetch(SERVER_BASE + '/gc', {
                        method: 'POST',
                        credentials: 'same-origin',
                        cache: 'no-cache',
                        headers: headers,
                        body: JSON.stringify(payload),
                    }).then(function (response) { return readAvatarImageGcJson(response, dryRun ? '扫描孤儿图片失败' : '清理孤儿图片失败'); })
                        .then(function (result) {
                            if (!Array.isArray(result.files) || !Number.isSafeInteger(result.removed) || result.removed < 0 ||
                                !Number.isFinite(result.bytes) || result.bytes < 0 || result.files.length !== result.removed ||
                                result.files.some(function (name) { return typeof name !== 'string' || !name; })) {
                                throw avatarImageGcError('后端返回了无效的孤儿图片清理结果', 'AVATAR_IMAGE_GC_INVALID');
                            }
                            return { files: result.files.slice(), removed: result.removed, bytes: result.bytes, capability: capability };
                        });
                });
            });
    }

    function formatAvatarMegabytes(bytes) { return (Math.max(0, Number(bytes) || 0) / (1024 * 1024)).toFixed(1) + 'MB'; }
    function openAvatarSettingsSheet() {
        var d = load();
        var state = avatarPageController ? avatarPageController.getState() : { count: 0, categories: 0, series: 0 };
        var storageState = avatarCoordinator ? avatarCoordinator.getState() : { phase: 'blocked' };
        var recoveryState = avatarRecoveryApi ? avatarRecoveryApi.getState() : { phase: 'blocked', locked: true };
        var authority = storageApi && typeof storageApi.getAuthorityState === 'function' ? storageApi.getAuthorityState() : { ready: false, localOnly: false };
        var recoveryPending = recoveryState.locked === true;
        var backupDisabled = !avatarTransferApi || recoveryPending || state.importing || state.exporting || storageState.phase === 'blocked' || storageState.phase === 'conflict';
        var restoreDisabled = !avatarRecoveryApi || recoveryPending || state.importing || state.exporting || authority.localOnly !== true || storageState.phase !== 'local-ready' || storageState.authoritative !== 'local';
        var updateState = getExtensionUpdateState();
        var updateView = getExtensionUpdateView(updateState);
        var interfaceHtml =
            '<div class="tm-row-inline"><label class="tm-setting-copy"><span>跟随当前美化外观</span><small>沿用美化管理器的颜色、圆角与面板质感</small></label><input type="checkbox" class="tm-chk" id="tm-avatar-follow-appearance" ' + (d.followThemeAppearance === true ? 'checked' : '') + '></div>' +
            '<div class="tm-row-inline"><label class="tm-setting-copy"><span>禁用聊天头像大图</span><small>点击聊天消息头像时不再打开酒馆的大图预览</small></label><input type="checkbox" class="tm-chk" id="tm-avatar-disable-chat-lightbox" ' + (d.disableChatAvatarLightbox === true ? 'checked' : '') + '></div>' +
            '<div class="tm-row-inline"><label class="tm-setting-copy"><span>自动隐藏顶栏内容</span><small>点击顶栏显示，点击其他区域再次隐藏</small></label><input type="checkbox" class="tm-chk" id="tm-avatar-auto-hide-header" ' + (d.autoHideHeader === true ? 'checked' : '') + '></div>';
        var organizeHtml =
            '<button class="tm-btn tm-btn-outline" id="tm-avatar-open-categories" style="width:100%;text-align:left"><i class="fa-solid fa-tags"></i> 管理分类（' + state.categories + '个）</button>';
        var dataHtml =
            '<div class="tm-storage-info">头像 ' + state.count + ' 张 / 分类 ' + state.categories + ' 个 / 系列 ' + state.series + ' 个</div>' +
            '<div class="tm-hint" id="tm-avatar-library-size" style="margin-bottom:9px">正在估算当前图库大小…</div>' +
            '<div class="tm-hint" style="margin-bottom:9px">完整备份包含头像主图、缩略图、分类整理、绑定、候选/激活、原头像显示调整和来源意图；不包含酒馆 Character/Persona 原图、其他美化设置或运行时缓存。</div>' +
            '<button class="tm-btn tm-btn-safe" id="tm-avatar-create-backup" style="width:100%;margin-bottom:9px"' + (backupDisabled ? ' disabled' : '') + '><i class="fa-solid fa-box-archive"></i> 创建完整备份</button>' +
            (recoveryPending
                ? '<div class="tm-hint" style="margin-bottom:9px;color:var(--warning-color,#d97706)">检测到未完成的头像恢复事务。Avatar Manager 与普通设置保存将保持只读，完成回滚前不会加载半恢复数据。</div><button class="tm-btn tm-btn-danger" id="tm-avatar-rollback-recovery" style="width:100%;margin-bottom:9px"><i class="fa-solid fa-rotate-left"></i> 回滚未完成的恢复</button>'
                : '<button class="tm-btn tm-btn-outline" id="tm-avatar-restore-backup" style="width:100%;margin-bottom:9px"' + (restoreDisabled ? ' disabled' : '') + '><i class="fa-solid fa-file-arrow-up"></i> 从完整备份恢复</button><input type="file" id="tm-avatar-restore-file" accept=".zip,application/zip" style="display:none">' +
                    (authority.localOnly === true ? '<div class="tm-hint" style="margin-bottom:9px">恢复会完整替换 Avatar Manager 数据，不会合并；旧头像库将保留为事务回滚依据。</div>' : '<div class="tm-hint" style="margin-bottom:9px">本阶段仅支持经明确确认的本地存储环境恢复；后端头像库不会被修改。</div>')) +
            '<div class="tm-data-danger"><div class="tm-data-group-label">后端空间清理</div>' +
            '<button class="tm-btn tm-btn-danger" id="tm-avatar-clean-orphan-images"' + (storageState.phase !== 'remote-ready' || storageState.authoritative !== 'remote' || storageState.writable !== true || recoveryPending ? ' disabled' : '') + '><i class="fa-solid fa-broom"></i><span><strong>清理孤儿图片</strong><small>先扫描，只删除未被美化或头像库引用且已保留 24 小时的后端图片</small></span></button>' +
            '<div class="tm-hint" style="margin-top:7px">仅新版 theme-mgr-server 支持；本地头像库无需执行此清理。</div></div>';
        var extensionHtml = '<div class="tm-update-panel' + (updateState.phase === 'ready' && updateState.available ? ' has-update' : '') + '"><div class="tm-update-panel-head"><div><strong>美化管理 v' + esc(TM_VERSION) + '</strong><span class="tm-update-status">' + esc(updateView.status) + '</span></div><button type="button" class="tm-btn tm-btn-outline tm-update-action" id="tm-avatar-update-action" data-update-mode="' + esc(updateView.mode) + '"' + (updateView.disabled ? ' disabled' : '') + '><i class="fa-solid ' + (updateView.mode === 'update' ? 'fa-download' : 'fa-rotate') + '"></i> ' + esc(updateView.action) + '</button></div><div class="tm-update-detail"' + (updateView.detail ? '' : ' hidden') + '>' + esc(updateView.detail) + '</div><div class="tm-plugin-credit"><span>作者：温水</span><span>发布于毛毛雨美化群、旅程</span></div></div>';
        var sheet = createSheet(['<div class="tm-sheet-title"><i class="fa-solid fa-sliders"></i>设置</div>', organizeHtml, buildDisclosureHtml('tm-avatar-settings-interface', '界面显示', 'fa-display', interfaceHtml), buildDisclosureHtml('tm-avatar-settings-data', '数据管理', 'fa-database', dataHtml), extensionHtml].join(''));
        sheet.classList.add('tm-sheet-tall', 'tm-settings-sheet');
        sheet.querySelector('#tm-avatar-follow-appearance').addEventListener('change', function () { var next = load(); next.followThemeAppearance = this.checked; save(next); syncManagerAppearance(); });
        sheet.querySelector('#tm-avatar-disable-chat-lightbox').addEventListener('change', function () { var next = load(); next.disableChatAvatarLightbox = this.checked; save(next); });
        sheet.querySelector('#tm-avatar-auto-hide-header').addEventListener('change', function () { var next = load(); next.autoHideHeader = this.checked; save(next); syncManagerAppearance(); });
        sheet.querySelector('#tm-avatar-open-categories').addEventListener('click', function () { closeSheet(sheet); avatarPageController.openCategoryManager(); });
        var sizeNode = sheet.querySelector('#tm-avatar-library-size');
        if (avatarTransferApi && typeof avatarTransferApi.estimateFullBackupSize === 'function') {
            avatarTransferApi.estimateFullBackupSize().then(function (info) {
                if (!sizeNode || !sizeNode.parentNode) return;
                var size = formatAvatarMegabytes(info.payloadBytes);
                sizeNode.textContent = info.payloadBytes > info.desktopPayloadLimit
                    ? '当前图库约 ' + size + '，已超过移动端 48MB 和桌面端 256MB 的完整备份安全上限；请分批导出图片'
                    : (info.payloadBytes > info.mobilePayloadLimit
                        ? '当前图库约 ' + size + '，超过移动端完整备份安全上限 48MB；可在桌面端备份或分批导出图片'
                        : '当前图库约 ' + size + '；移动端完整备份安全上限为 48MB。');
            }).catch(function () { if (sizeNode && sizeNode.parentNode) sizeNode.textContent = '当前图库大小估算失败；创建备份时仍会执行完整安全检查。'; });
        }
        sheet.querySelector('#tm-avatar-create-backup').addEventListener('click', function () {
            var button = this;
            var original = button.innerHTML;
            button.disabled = true;
            button.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> 正在校验并创建…';
            avatarTransferApi.createFullBackup().then(function (result) {
                toast(result.source && result.source.consistency === 'last-known-good' ? '完整备份已创建（离线最后已验证副本）' : '完整备份已创建并通过校验');
            }).catch(function (error) {
                toast(error && error.message ? error.message : '完整备份创建失败', true);
            }).finally(function () {
                button.innerHTML = original;
                var current = avatarCoordinator && avatarCoordinator.getState();
                button.disabled = !avatarTransferApi || avatarRecoveryGateLocked || !current || current.phase === 'blocked' || current.phase === 'conflict';
            });
        });
        var restoreButton = sheet.querySelector('#tm-avatar-restore-backup');
        var restoreInput = sheet.querySelector('#tm-avatar-restore-file');
        if (restoreButton && restoreInput) {
            restoreButton.addEventListener('click', function () { restoreInput.click(); });
            restoreInput.addEventListener('change', function () {
                var file = this.files && this.files[0];
                this.value = '';
                if (!file) return;
                var original = restoreButton.innerHTML;
                restoreButton.disabled = true;
                restoreButton.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> 正在验证备份…';
                avatarRecoveryApi.inspectBackup(file).then(function (verified) {
                    var sourceText = verified.manifest.source.consistency === 'last-known-good' ? '离线最后已验证副本' : '完整已验证副本';
                    if (!confirm('从此完整备份恢复 Avatar Manager？\n\n备份包含 ' + verified.inventory.assets.length + ' 张头像（' + sourceText + '）。\n当前头像资产、分类、系列、绑定与显示调整将被完整替换，不会合并。\n旧头像库会保留用于事务回滚。')) return null;
                    restoreButton.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> 正在事务恢复…';
                    return avatarRecoveryApi.restoreBackup(file);
                }).then(function (result) {
                    if (!result) return;
                    closeSheet(sheet);
                    if (avatarRuntime) { avatarRuntime.stop(); avatarRuntime.start().catch(function () {}); }
                    if (avatarPageController) avatarPageController.refresh().catch(function () {});
                    toast('完整备份恢复成功：' + result.assets + ' 张头像');
                }).catch(function (error) {
                    toast(error && error.message ? error.message : '完整备份恢复失败', true);
                }).finally(function () {
                    if (!restoreButton.parentNode) return;
                    restoreButton.innerHTML = original;
                    restoreButton.disabled = avatarRecoveryGateLocked;
                });
            });
        }
        var rollbackButton = sheet.querySelector('#tm-avatar-rollback-recovery');
        if (rollbackButton) rollbackButton.addEventListener('click', function () {
            if (!confirm('回滚未完成的头像恢复事务？\n只会恢复日志中经过校验的原活动头像库与原头像分类设置，不会猜测修复。')) return;
            var original = rollbackButton.innerHTML;
            rollbackButton.disabled = true;
            rollbackButton.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> 正在校验并回滚…';
            avatarRecoveryApi.rollbackIncomplete().then(function () {
                closeSheet(sheet);
                if (bindingController) bindingController.start();
                if (avatarRuntime) avatarRuntime.start().catch(function () {});
                if (avatarPageController) avatarPageController.refresh().catch(function () {});
                toast('未完成的头像恢复已安全回滚');
            }).catch(function (error) {
                toast(error && error.message ? error.message : '恢复事务回滚失败；仍保持只读', true);
                rollbackButton.innerHTML = original;
                rollbackButton.disabled = false;
            });
        });
        var orphanImageButton = sheet.querySelector('#tm-avatar-clean-orphan-images');
        if (orphanImageButton) orphanImageButton.addEventListener('click', function () {
            var button = orphanImageButton;
            var original = button.innerHTML;
            button.disabled = true;
            button.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> 正在安全扫描…';
            requestAvatarImageGc(true).then(function (scan) {
                if (!scan.removed) {
                    toast('没有可清理的孤儿图片');
                    return null;
                }
                var graceHours = Math.max(1, Math.round((Number(scan.capability.graceMs) || 86400000) / 3600000));
                if (!confirm('扫描到 ' + scan.removed + ' 张孤儿图片，共 ' + formatAvatarMegabytes(scan.bytes) + '。\n\n这些文件未被美化或头像库引用，并且已超过 ' + graceHours + ' 小时保护期。\n删除后无法恢复，确定继续吗？')) return null;
                button.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> 正在清理…';
                return requestAvatarImageGc(false, scan.files);
            }).then(function (result) {
                if (!result) return;
                toast('已清理 ' + result.removed + ' 张孤儿图片，释放约 ' + formatAvatarMegabytes(result.bytes));
            }).catch(function (error) {
                toast(error && error.message ? error.message : '清理孤儿图片失败', true);
            }).finally(function () {
                if (!button.parentNode) return;
                button.innerHTML = original;
                var current = avatarCoordinator && avatarCoordinator.getState();
                button.disabled = avatarRecoveryGateLocked || !current || current.phase !== 'remote-ready' || current.authoritative !== 'remote' || current.writable !== true;
            });
        });
        sheet.querySelector('#tm-avatar-update-action').addEventListener('click', function () { var current = getExtensionUpdateState(); if (current.phase === 'ready' && current.available) openExtensionUpdateConfirmSheet(); else { this.disabled = true; checkExtensionUpdate(true).catch(function () { toast('检查更新失败；请检查网络、Git 状态或酒馆服务日志', true); }); } });
        syncExtensionUpdatePanel();
        return sheet;
    }

